window.__LEC=[{"id":"r-a1-1","level":"A1","title":"Je m'appelle Camille","theme":"Presentación personal","emoji":"👋","intro":"Camille, una estudiante francesa de Lyon, se presenta y habla de su día a día.","text":"Bonjour ! Je m'appelle Camille. J'ai vingt ans et je suis française. J'habite à Lyon, une grande ville dans le sud-est de la France. Je suis étudiante à l'université. J'étudie l'espagnol et l'anglais.\n\nLe matin, je prends le bus pour aller à la fac. J'aime beaucoup mes cours, mais je n'aime pas le lundi ! Le soir, je fais du sport avec mon amie Sofia. Elle est colombienne, de Bogotá. Nous parlons en français et en espagnol. C'est très pratique !","gloss":[["Je m'appelle","me llamo"],["J'ai vingt ans","tengo veinte años (en francés se usa avoir: «tener»)"],["J'habite","vivo"],["une grande ville","una ciudad grande"],["sud-est","sureste"],["étudiante","estudiante (mujer)"],["Le matin","por la mañana"],["je prends le bus","tomo el bus"],["la fac","la universidad (forma familiar de «faculté»)"],["je n'aime pas","no me gusta"],["Le soir","por la noche"],["je fais du sport","hago deporte"],["pratique","práctico"]],"questions":[{"q":"¿Cuántos años tiene Camille?","o":["Dieciocho","Veinte","Veintidós"],"a":1,"why":"El texto dice «J'ai vingt ans»: vingt = veinte."},{"q":"¿Qué estudia Camille?","o":["Español e inglés","Francés y alemán","Medicina"],"a":0,"why":"Camille dice «J'étudie l'espagnol et l'anglais»."},{"q":"¿Qué día no le gusta a Camille?","o":["El viernes","El domingo","El lunes"],"a":2,"why":"Ella dice «je n'aime pas le lundi»: le lundi = el lunes."},{"q":"¿Qué hace Camille por la noche?","o":["Estudia en la biblioteca","Hace deporte con Sofia","Toma el bus a la universidad"],"a":1,"why":"El texto dice «Le soir, je fais du sport avec mon amie Sofia»."}],"voice":"f"},{"id":"r-a1-2","level":"A1","title":"Le samedi au marché","theme":"Comida y compras","emoji":"🧺","intro":"Paul y su abuela van al mercado un sábado: ¿qué compran?","text":"C'est samedi. Paul va au marché avec sa grand-mère. Le marché est sur la place, près de l'église. Il y a beaucoup de monde.\n\nPaul achète des pommes, des tomates et du fromage. Sa grand-mère achète du pain et des fleurs. Les fraises sont très belles, mais elles sont chères : six euros le kilo !\n\nAprès, ils vont au café. Paul prend un chocolat chaud et sa grand-mère prend un café. Ils sont contents. Le samedi, c'est leur jour préféré.","gloss":[["au marché","al mercado"],["sa grand-mère","su abuela"],["près de","cerca de"],["Il y a beaucoup de monde","hay mucha gente"],["achète","compra (verbo acheter)"],["des pommes","unas manzanas"],["du fromage","queso"],["du pain","pan"],["des fleurs","flores"],["Les fraises","las fresas"],["chères","caras (precio alto)"],["Après","después"],["un chocolat chaud","un chocolate caliente"],["préféré","favorito, preferido"]],"questions":[{"q":"¿Con quién va Paul al mercado?","o":["Con un amigo","Con su madre","Con su abuela"],"a":2,"why":"El texto dice «Paul va au marché avec sa grand-mère»: grand-mère = abuela."},{"q":"¿Qué compra la abuela?","o":["Pan y flores","Manzanas y queso","Fresas"],"a":0,"why":"«Sa grand-mère achète du pain et des fleurs»."},{"q":"¿Cuánto cuestan las fresas?","o":["Seis euros el kilo","Dos euros el kilo","Cuatro euros el kilo"],"a":0,"why":"El texto dice «elles sont chères : six euros le kilo»."},{"q":"¿Qué toma Paul en el café?","o":["Un café","Un chocolate caliente","Un té"],"a":1,"why":"«Paul prend un chocolat chaud»: toma un chocolate caliente; el café es para la abuela."}],"voice":"m"},{"id":"r-a1-3","level":"A1","title":"Un message de Montréal","theme":"Viajes y Québec","emoji":"❄️","intro":"Laura está de viaje en Montreal y le escribe un mensaje a su amigo Diego, en Pamplona.","text":"Salut Diego !\n\nJe suis à Montréal, au Québec, avec ma classe. Il fait très froid : moins dix degrés ! Il y a de la neige partout. C'est magnifique.\n\nIci, les gens parlent français, mais avec un accent différent. Aujourd'hui, nous mangeons une poutine : ce sont des frites avec du fromage et une sauce. C'est délicieux !\n\nDemain, nous allons au Vieux-Montréal. C'est le quartier historique de la ville. Et toi, ça va à Pamplona ? Tu as chaud ?\n\nBises,\nLaura","gloss":[["Salut","hola (informal)"],["Il fait très froid","hace mucho frío"],["moins dix degrés","menos diez grados"],["de la neige","nieve"],["partout","por todas partes"],["les gens","la gente"],["nous mangeons","comemos"],["des frites","papas fritas"],["Demain","mañana (el día siguiente)"],["nous allons","vamos"],["le quartier","el barrio"],["Et toi","¿y tú?"],["Tu as chaud ?","¿tienes calor?"],["Bises","besos (despedida informal entre amigos)"]],"questions":[{"q":"¿Dónde está Laura?","o":["En Montreal","En París","En Pamplona"],"a":0,"why":"Laura escribe «Je suis à Montréal, au Québec»."},{"q":"¿Qué tiempo hace en Montreal?","o":["Calor y sol","Llueve mucho","Mucho frío y nieve"],"a":2,"why":"«Il fait très froid : moins dix degrés ! Il y a de la neige partout»."},{"q":"¿Qué es la poutine?","o":["Una sopa de verduras","Papas fritas con queso y salsa","Un postre con chocolate"],"a":1,"why":"El texto explica: «ce sont des frites avec du fromage et une sauce»."},{"q":"¿Qué es el Vieux-Montréal?","o":["Un restaurante","Una universidad","El barrio histórico"],"a":2,"why":"Laura dice «C'est le quartier historique de la ville»."}],"voice":"f"},{"id":"r-a2-1","level":"A2","title":"Ma colocation à Toulouse","theme":"Vida estudiantil","emoji":"🏠","intro":"Un estudiante colombiano cuenta cómo es compartir apartamento con otros tres estudiantes en Toulouse.","text":"Depuis septembre, j'habite dans une colocation à Toulouse avec trois autres étudiants : Inès, une Marocaine, Tom, un Belge, et Mathilde, qui vient de Bretagne. L'appartement est grand et lumineux, mais la cuisine est un peu petite.\n\nAu début, ce n'était pas facile. Tom laissait toujours la vaisselle sale dans l'évier ! Alors, nous avons fait un tableau avec les tâches de chaque personne. Maintenant, tout va mieux.\n\nLe week-end dernier, nous avons organisé un dîner international. Inès a préparé un couscous, Tom a fait des gaufres et moi, j'ai cuisiné des arepas. Nos voisins sont venus aussi. C'était une soirée super !\n\nLa vie en colocation, c'est moins cher et on n'est jamais seul.","gloss":[["une colocation","un apartamento compartido"],["lumineux","iluminado, con mucha luz"],["Au début","al principio"],["laissait","dejaba (imperfecto de laisser)"],["la vaisselle sale","los platos sucios"],["l'évier","el lavaplatos (fregadero)"],["un tableau","un cuadro, una tabla"],["les tâches","las tareas"],["tout va mieux","todo va mejor"],["Le week-end dernier","el fin de semana pasado"],["des gaufres","gofres, waffles (típicos de Bélgica)"],["Nos voisins","nuestros vecinos"],["une soirée","una velada, una fiesta por la noche"],["moins cher","más barato"]],"questions":[{"q":"¿Cuántas personas viven en el apartamento, contando al narrador?","o":["Tres","Cuatro","Cinco"],"a":1,"why":"El narrador vive «avec trois autres étudiants»: tres más él, cuatro en total."},{"q":"¿Cuál era el problema al principio?","o":["Tom dejaba siempre los platos sucios","La cocina era demasiado grande","Los vecinos hacían mucho ruido"],"a":0,"why":"El texto dice «Tom laissait toujours la vaisselle sale dans l'évier»."},{"q":"¿Qué preparó el narrador para la cena internacional?","o":["Un cuscús","Gofres","Arepas"],"a":2,"why":"«Moi, j'ai cuisiné des arepas»; el cuscús lo hizo Inès y los gofres, Tom."},{"q":"Según el narrador, ¿qué ventaja tiene vivir en colocation?","o":["Está cerca de la universidad","Es más barato y uno nunca está solo","La cocina es muy grande"],"a":1,"why":"La última frase dice «c'est moins cher et on n'est jamais seul»."}],"voice":"m"},{"id":"r-a2-2","level":"A2","title":"Aminata, la musique dans le sang","theme":"Música y Senegal","emoji":"🥁","intro":"Aminata vive en Dakar, la capital de Senegal, y la música es su gran pasión.","text":"Aminata a vingt-deux ans. Elle habite à Dakar, la capitale du Sénégal. Au Sénégal, on parle wolof et français. Aminata parle les deux langues, et elle apprend aussi l'anglais.\n\nAminata adore la musique. Le vendredi soir, elle va avec ses amis dans un petit club du centre-ville pour écouter du mbalax, une musique sénégalaise avec beaucoup de percussions. Le chanteur le plus célèbre de ce style est Youssou N'Dour.\n\nL'année dernière, Aminata a commencé des cours de djembé, un tambour africain. C'est difficile, mais elle pratique tous les jours. Son rêve ? Jouer un jour dans un grand festival en Europe. « La musique, dit-elle, c'est la meilleure façon de partager notre culture. »","gloss":[["les deux langues","las dos lenguas"],["elle apprend","aprende (verbo apprendre)"],["Le vendredi soir","los viernes por la noche"],["écouter","escuchar"],["le plus célèbre","el más famoso"],["L'année dernière","el año pasado"],["a commencé","empezó (passé composé de commencer)"],["un tambour","un tambor"],["tous les jours","todos los días"],["Son rêve","su sueño (lo que desea)"],["Jouer","tocar (un instrumento)"],["la meilleure façon","la mejor manera"],["partager","compartir"]],"questions":[{"q":"Según el texto, ¿qué lenguas se hablan en Senegal?","o":["Inglés y francés","Solo wolof","Wolof y francés"],"a":2,"why":"El texto dice «Au Sénégal, on parle wolof et français». El inglés es una lengua que Aminata aprende."},{"q":"¿Qué es el mbalax?","o":["Un instrumento","Una música senegalesa con muchas percusiones","Un club de Dakar"],"a":1,"why":"«du mbalax, une musique sénégalaise avec beaucoup de percussions»."},{"q":"¿Qué hace Aminata desde el año pasado?","o":["Toma clases de djembé","Canta en festivales en Europa","Estudia inglés en Londres"],"a":0,"why":"«L'année dernière, Aminata a commencé des cours de djembé»."},{"q":"En el texto, «Jouer» significa…","o":["Jugar un partido","Tocar un instrumento en público","Bailar"],"a":1,"why":"Aquí «jouer dans un festival» es tocar música: con instrumentos, jouer = tocar."}],"voice":"f"},{"id":"r-a2-3","level":"A2","title":"Une journée sans téléphone","theme":"Tecnología","emoji":"📵","intro":"Un estudiante acepta un reto de su profesor: pasar un día entero sin celular.","text":"Mardi dernier, mon professeur de sociologie nous a proposé un défi : passer une journée entière sans téléphone portable. J'ai accepté, mais j'étais un peu nerveux.\n\nLe matin, sans mon réveil électronique, je me suis réveillé en retard ! Dans le bus, je n'ai pas regardé mes messages. J'ai observé les gens et le paysage. Tout le monde avait les yeux sur son écran.\n\nÀ midi, j'ai déjeuné avec mes camarades et nous avons vraiment parlé, sans interruption. L'après-midi, j'ai lu un livre à la bibliothèque. Le soir, j'étais fatigué mais calme.\n\nConclusion : le téléphone est utile, mais je vais essayer de l'utiliser moins. Et vous, vous pouvez vivre une journée sans lui ?","gloss":[["un défi","un reto, un desafío"],["une journée entière","un día entero"],["téléphone portable","teléfono celular"],["réveil","despertador"],["en retard","tarde, con retraso"],["le paysage","el paisaje"],["Tout le monde","todo el mundo"],["son écran","su pantalla"],["j'ai déjeuné","almorcé"],["vraiment","realmente, de verdad"],["j'ai lu","leí (passé composé de lire)"],["fatigué","cansado"],["essayer de","intentar"],["sans lui","sin él"]],"questions":[{"q":"¿Quién propuso el reto?","o":["Un amigo","Sus padres","Su profesor de sociología"],"a":2,"why":"«Mon professeur de sociologie nous a proposé un défi»."},{"q":"¿Qué problema tuvo por la mañana?","o":["Se despertó tarde","Perdió el bus","Olvidó su libro"],"a":0,"why":"Sin su despertador electrónico: «je me suis réveillé en retard»."},{"q":"¿Qué observó en el bus?","o":["La gente leía libros","Todo el mundo miraba su pantalla","El bus estaba vacío"],"a":1,"why":"«Tout le monde avait les yeux sur son écran»."},{"q":"¿Cuál es su conclusión?","o":["Nunca más va a usar el teléfono","El reto fue inútil","Va a intentar usar menos el teléfono"],"a":2,"why":"«Le téléphone est utile, mais je vais essayer de l'utiliser moins»."}],"voice":"m"},{"id":"r-a2-4","level":"A2","title":"Bruxelles, capitale de la BD","theme":"Cómic y Bélgica","emoji":"💬","intro":"Bruselas es la capital de Bélgica… y también la capital del cómic. Descubre por qué.","text":"Bruxelles est la capitale de la Belgique, mais c'est aussi la capitale de la bande dessinée. Dans les rues, on peut voir plus de cinquante grandes fresques avec des personnages de BD sur les murs des maisons. C'est un parcours très original pour découvrir la ville à pied.\n\nBeaucoup de héros célèbres sont belges : Tintin, le jeune reporter, et les Schtroumpfs, de petits personnages bleus. En Colombie, on les connaît aussi !\n\nSi vous visitez Bruxelles, allez au Centre belge de la bande dessinée. Le bâtiment est magnifique et il y a des expositions très intéressantes. Ensuite, goûtez une gaufre ou des frites. Attention : pour les Belges, les frites sont belges, pas françaises !","gloss":[["la bande dessinée","el cómic, la historieta (abreviado: BD)"],["des fresques","murales"],["des personnages","personajes"],["les murs","las paredes, los muros"],["un parcours","un recorrido"],["découvrir","descubrir"],["à pied","a pie"],["les Schtroumpfs","los Pitufos"],["on les connaît","los conocemos"],["Le bâtiment","el edificio"],["Ensuite","luego, después"],["goûtez","prueben (imperativo de goûter)"],["Attention","¡ojo!, ¡cuidado!"]],"questions":[{"q":"¿Por qué Bruselas es la «capital del cómic»?","o":["Hay murales con personajes de cómic en sus calles","Todas sus librerías venden cómics","Solo allí se puede leer Tintin"],"a":0,"why":"El texto dice que hay «plus de cinquante grandes fresques avec des personnages de BD sur les murs»."},{"q":"Según el texto, «les Schtroumpfs» son…","o":["Unos periodistas belgas","Unos personajes pequeños y azules","Unos cocineros famosos"],"a":1,"why":"«les Schtroumpfs, de petits personnages bleus»: en español, los Pitufos."},{"q":"¿Qué lugar recomienda visitar el texto?","o":["El Parlamento europeo","Un museo del chocolate","El Centro belga del cómic"],"a":2,"why":"«Allez au Centre belge de la bande dessinée»."},{"q":"Para los belgas, las papas fritas son…","o":["Belgas","Francesas","Colombianas"],"a":0,"why":"«Pour les Belges, les frites sont belges, pas françaises !»"}],"voice":"f"},{"id":"r-b1-1","level":"B1","title":"Six mois à Lille","theme":"Intercambio universitario","emoji":"🎒","intro":"Valentina, estudiante de lenguas en Pamplona, cuenta su semestre de intercambio en el norte de Francia.","text":"Quand Valentina a reçu la lettre d'acceptation de l'Université de Lille, elle a sauté de joie. Étudiante en langues étrangères à Pamplona, en Colombie, elle rêvait depuis longtemps de vivre en France. Pourtant, les premières semaines ont été plus difficiles que prévu.\n\n« Je croyais que je parlais bien français, raconte-t-elle, mais dans la rue, les gens parlaient si vite que je ne comprenais presque rien ! » Le climat aussi l'a surprise : en novembre, il faisait déjà nuit à cinq heures de l'après-midi, et il pleuvait souvent.\n\nPetit à petit, pourtant, les choses ont changé. Valentina s'est inscrite dans une association d'étudiants internationaux, où elle a rencontré des jeunes du monde entier. Elle a aussi trouvé un petit boulot dans une librairie, ce qui l'a obligée à parler avec les clients tous les jours.\n\nAujourd'hui, de retour en Colombie, elle conseille à ses camarades de partir sans hésiter : « On ne progresse jamais autant que lorsqu'on sort de sa zone de confort. »","gloss":[["a sauté de joie","saltó de alegría"],["elle rêvait depuis longtemps","soñaba desde hacía mucho tiempo"],["Pourtant","sin embargo"],["plus difficiles que prévu","más difíciles de lo previsto"],["si vite","tan rápido"],["presque rien","casi nada"],["il faisait déjà nuit","ya era de noche"],["Petit à petit","poco a poco"],["s'est inscrite","se inscribió"],["un petit boulot","un trabajo temporal, un «trabajito» (familiar)"],["une librairie","una librería (¡no una biblioteca, que es bibliothèque!)"],["de retour","de regreso"],["sans hésiter","sin dudar"],["autant que","tanto como"]],"questions":[{"q":"¿Qué estudia Valentina en Colombia?","o":["Lenguas extranjeras","Turismo","Literatura francesa"],"a":0,"why":"El texto la presenta como «Étudiante en langues étrangères à Pamplona»."},{"q":"¿Cuál fue su primera dificultad con el idioma?","o":["No entendía los textos escritos","La gente hablaba tan rápido que casi no entendía","Nadie quería hablar con ella"],"a":1,"why":"Ella dice: «les gens parlaient si vite que je ne comprenais presque rien»."},{"q":"En el texto, «un petit boulot» significa…","o":["Un barco pequeño","Una clase particular","Un trabajo temporal"],"a":2,"why":"«Un petit boulot» es un trabajo sencillo o temporal; aquí, en una librería."},{"q":"¿Por qué el trabajo en la librería ayudó a Valentina? (inferencia)","o":["Porque ganaba mucho dinero","Porque tenía que hablar francés todos los días con los clientes","Porque podía leer libros en español"],"a":1,"why":"El texto dice que el trabajo «l'a obligée à parler avec les clients tous les jours»: practicaba el idioma a diario."},{"q":"¿Qué actitud tiene Valentina hoy frente a su experiencia?","o":["Lamenta haberse ido","Prefiere no volver a Francia","Recomienda vivirla sin dudar"],"a":2,"why":"«Elle conseille à ses camarades de partir sans hésiter»."}],"voice":"f"},{"id":"r-b1-2","level":"B1","title":"Les frigos solidaires","theme":"Medio ambiente","emoji":"🥕","intro":"Neveras en la calle para compartir comida: una idea simple contra el desperdicio en Francia.","text":"En France, chaque habitant jette en moyenne une trentaine de kilos de nourriture par an. Pour lutter contre ce gaspillage, une idée simple se développe dans plusieurs villes : les frigos solidaires.\n\nLe principe est facile à comprendre. Un réfrigérateur est installé dans la rue, devant un commerce ou une association. Les habitants, les restaurants et les boulangeries peuvent y déposer les produits qu'ils ne vont pas consommer : des légumes, du pain, des yaourts… Ensuite, n'importe qui peut se servir gratuitement, sans donner son nom.\n\nBien sûr, il y a des règles. On ne peut pas déposer de viande crue ni d'aliments dont la date est dépassée. Des bénévoles passent chaque jour pour nettoyer le frigo et vérifier les produits.\n\nPour Karim, étudiant à Marseille, c'est une vraie aide : « À la fin du mois, quand mon budget est serré, je viens chercher des fruits. Et quand j'ai fait trop de courses, je laisse quelque chose à mon tour. » Un geste pour la planète, mais aussi pour les autres.","gloss":[["jette","tira, bota (verbo jeter)"],["en moyenne","en promedio"],["une trentaine","unos treinta"],["lutter contre","luchar contra"],["gaspillage","desperdicio"],["n'importe qui","cualquier persona"],["se servir","servirse, tomar lo que uno necesita"],["gratuitement","gratis"],["viande crue","carne cruda"],["dépassée","vencida (fecha de caducidad)"],["Des bénévoles","voluntarios (personas que trabajan sin cobrar)"],["serré","ajustado, apretado"],["courses","compras (del mercado)"],["à mon tour","a mi vez"]],"questions":[{"q":"¿Qué es un «frigo solidaire»?","o":["Un restaurante barato para estudiantes","Una nevera en la calle donde se deja y se toma comida gratis","Una tienda que vende productos vencidos"],"a":1,"why":"Es un refrigerador en la calle donde se depositan productos y «n'importe qui peut se servir gratuitement»."},{"q":"¿Qué está prohibido depositar?","o":["Carne cruda","Pan","Yogures"],"a":0,"why":"«On ne peut pas déposer de viande crue ni d'aliments dont la date est dépassée»."},{"q":"En el texto, «Des bénévoles» son personas que…","o":["venden los productos","controlan a los usuarios","ayudan sin cobrar"],"a":2,"why":"Un bénévole es un voluntario: trabaja sin recibir dinero, aquí para limpiar y revisar la nevera."},{"q":"¿Por qué, probablemente, no hay que dar el nombre para tomar comida? (inferencia)","o":["Para que nadie sienta vergüenza al usar la nevera","Porque los voluntarios no tienen tiempo","Porque la ley prohíbe preguntar nombres"],"a":0,"why":"El texto dice «sans donner son nom»: el anonimato permite que personas con el presupuesto «serré», como Karim, se sirvan sin sentirse juzgadas."},{"q":"¿Qué hace Karim cuando ha comprado demasiado?","o":["Lo tira","Deja algo en la nevera","Lo vende a sus vecinos"],"a":1,"why":"«Quand j'ai fait trop de courses, je laisse quelque chose à mon tour»."}],"voice":"m"},{"id":"r-b1-3","level":"B1","title":"Le FESPACO, fête du cinéma africain","theme":"Cine africano","emoji":"🎬","intro":"Cada dos años, Uagadugú, en Burkina Faso, se convierte en la capital del cine africano.","text":"Tous les deux ans, la ville de Ouagadougou, capitale du Burkina Faso, devient la capitale du cinéma africain. Pendant une semaine, le FESPACO, le plus grand festival de cinéma du continent, attire des réalisateurs, des acteurs et des milliers de spectateurs venus de toute l'Afrique et d'ailleurs.\n\nCréé en 1969, ce festival avait un objectif clair : permettre aux Africains de voir des films qui racontent leurs propres histoires, avec leurs langues et leurs paysages, et pas seulement des films venus d'Europe ou des États-Unis. Le prix le plus important s'appelle l'Étalon d'or de Yennenga, en hommage à une princesse légendaire de la région.\n\nPendant le festival, l'ambiance est extraordinaire. On projette des films dans de grandes salles, mais aussi en plein air, sur des places publiques. Les discussions après les séances sont souvent passionnées.\n\nPour les étudiants en langues, le FESPACO est une occasion unique de découvrir la diversité du français parlé en Afrique et de comprendre qu'une langue appartient à tous ceux qui la parlent.","gloss":[["Tous les deux ans","cada dos años"],["attire","atrae"],["des réalisateurs","directores de cine"],["d'ailleurs","de otros lugares"],["leurs propres histoires","sus propias historias"],["pas seulement","no solamente"],["l'Étalon d'or","el Semental de oro (étalon = caballo semental)"],["en hommage à","en homenaje a"],["l'ambiance","el ambiente"],["On projette","se proyectan"],["en plein air","al aire libre"],["les séances","las funciones (de cine)"],["passionnées","apasionadas"],["appartient à","pertenece a"]],"questions":[{"q":"¿Cada cuánto se celebra el FESPACO?","o":["Cada año","Cada dos años","Cada cinco años"],"a":1,"why":"El texto empieza con «Tous les deux ans»: cada dos años."},{"q":"¿Cuál era el objetivo del festival en 1969?","o":["Promover el cine europeo en África","Formar actores para Hollywood","Que los africanos vieran películas con sus propias historias"],"a":2,"why":"«Permettre aux Africains de voir des films qui racontent leurs propres histoires»."},{"q":"En el texto, «en plein air» significa…","o":["Al aire libre","En salas llenas","En televisión"],"a":0,"why":"Se opone a «dans de grandes salles»: las películas se proyectan también afuera, «sur des places publiques»."},{"q":"¿Qué podemos deducir sobre el cine en África antes de 1969? (inferencia)","o":["Estaba prohibido","El público veía sobre todo películas extranjeras","Solo existían películas en wolof"],"a":1,"why":"Si el objetivo era mostrar películas africanas «et pas seulement des films venus d'Europe ou des États-Unis», es que dominaban las películas extranjeras."},{"q":"¿Qué idea sobre el francés expresa la última frase?","o":["El francés pertenece a todos sus hablantes","El verdadero francés es el de Francia","El francés africano es difícil de entender"],"a":0,"why":"«Une langue appartient à tous ceux qui la parlent»: no tiene un único dueño."}],"voice":"m"},{"id":"r-b1-4","level":"B1","title":"Télétravail : trois points de vue","theme":"Mundo laboral","emoji":"💻","intro":"¿El teletrabajo es una ventaja o un problema? Tres jóvenes profesionales francófonos responden.","text":"Depuis quelques années, le télétravail fait partie de la vie de nombreux jeunes professionnels. Mais est-ce vraiment un avantage ? Trois jeunes nous répondent.\n\nLéa, 26 ans, graphiste à Nantes : « Pour moi, c'est parfait. Je gagne deux heures par jour parce que je n'ai plus besoin de prendre le train. J'organise mon temps comme je veux et je suis plus concentrée à la maison. »\n\nJulien, 29 ans, développeur à Paris : « Au début, j'étais ravi. Mais après quelques mois, je me sentais seul. Mes collègues me manquaient, surtout les pauses café et les discussions informelles. Maintenant, je vais au bureau trois jours par semaine. »\n\nFatou, 24 ans, traductrice à Dakar : « Grâce au télétravail, je travaille pour une entreprise canadienne sans quitter le Sénégal. Le seul problème, c'est le décalage horaire : parfois, j'ai des réunions à dix heures du soir ! »\n\nFinalement, il n'existe pas de solution idéale : tout dépend de la personnalité et du métier de chacun.","gloss":[["le télétravail","el teletrabajo, trabajo remoto"],["fait partie de","forma parte de"],["graphiste","diseñadora gráfica"],["Je gagne deux heures","gano (ahorro) dos horas"],["je n'ai plus besoin de","ya no necesito"],["ravi","encantado"],["je me sentais seul","me sentía solo"],["Mes collègues me manquaient","extrañaba a mis colegas"],["surtout","sobre todo"],["Grâce au","gracias al"],["sans quitter","sin salir de"],["le décalage horaire","la diferencia horaria"],["des réunions","reuniones"],["métier","oficio, profesión"]],"questions":[{"q":"¿Qué ventaja del teletrabajo menciona Léa?","o":["Gana un salario más alto","Ahorra el tiempo del transporte","Ve más a sus colegas"],"a":1,"why":"«Je gagne deux heures par jour parce que je n'ai plus besoin de prendre le train»."},{"q":"¿Por qué Julien cambió de opinión?","o":["Porque se sentía solo","Porque su jefe lo obligó","Porque su conexión a internet era mala"],"a":0,"why":"«Après quelques mois, je me sentais seul»."},{"q":"«Mes collègues me manquaient» significa…","o":["Mis colegas me faltaban al respeto","Mis colegas no venían a trabajar","Echaba de menos a mis colegas"],"a":2,"why":"El verbo manquer à quelqu'un expresa nostalgia: «X me manque» = extraño a X. ¡La construcción está invertida respecto al español «extrañar»!"},{"q":"¿Por qué Fatou tiene a veces reuniones a las diez de la noche? (inferencia)","o":["Porque prefiere trabajar de noche","Porque su empresa está en otro continente, con otro horario","Porque en Dakar las oficinas abren tarde"],"a":1,"why":"Trabaja para «une entreprise canadienne» desde Senegal: el «décalage horaire» obliga a reuniones tarde en Dakar."},{"q":"¿Cuál es la conclusión del texto?","o":["El teletrabajo es siempre la mejor opción","Todos deberían volver a la oficina","Depende de la personalidad y del oficio de cada uno"],"a":2,"why":"«Il n'existe pas de solution idéale : tout dépend de la personnalité et du métier de chacun»."}],"voice":"f"},{"id":"r-b2-1","level":"B2","title":"Faut-il bannir le téléphone en cours ?","theme":"Debate educativo","emoji":"📱","intro":"Una profesora universitaria da su opinión sobre la prohibición de los celulares en clase. Atención a sus argumentos y a su tono.","text":"Il suffit d'entrer dans un amphithéâtre pendant un cours magistral pour s'en rendre compte : derrière les ordinateurs ouverts, une bonne partie des étudiants consulte les réseaux sociaux, répond à des messages ou regarde des vidéos. Face à ce constat, certaines universités envisagent d'interdire purement et simplement les téléphones pendant les cours. La mesure est-elle justifiée ?\n\nSes partisans avancent des arguments solides. Plusieurs études suggèrent que la simple présence d'un smartphone sur la table réduit la capacité de concentration, même lorsqu'il est éteint. Par ailleurs, l'étudiant distrait ne se pénalise pas seulement lui-même : il détourne aussi l'attention de ses voisins, qui voient défiler des vidéos sur son écran.\n\nPourtant, une interdiction totale me paraît à la fois naïve et contre-productive. Naïve, parce qu'il est illusoire de vouloir surveiller des centaines d'adultes. Contre-productive, parce que le téléphone est aussi un outil de travail : dictionnaire, calculatrice, accès aux documents du cours. Interdire, c'est renoncer à éduquer à un usage raisonnable.\n\nPlutôt que de sanctionner, pourquoi ne pas repenser nos cours ? Un enseignant qui parle pendant deux heures sans interruption ne devrait pas s'étonner de perdre son public. Des activités courtes, des questions, des moments de discussion : voilà sans doute le meilleur remède contre la distraction. Et si le problème n'était pas le téléphone, mais notre façon d'enseigner ?\n\nClaire Morel, maîtresse de conférences en sciences de l'éducation","gloss":[["un amphithéâtre","un auditorio universitario («amphi» en lenguaje estudiantil)"],["un cours magistral","una clase magistral"],["s'en rendre compte","darse cuenta de ello"],["Face à ce constat","ante esta constatación"],["envisagent","contemplan, consideran"],["Ses partisans","sus defensores"],["avancent","presentan, exponen (argumentos)"],["éteint","apagado"],["Par ailleurs","por otra parte, además"],["détourne","desvía"],["un outil","una herramienta"],["Plutôt que de","en lugar de"],["s'étonner","sorprenderse"],["remède","remedio"]],"questions":[{"q":"Quelle mesure certaines universités envisagent-elles ?","o":["Supprimer les cours magistraux","Interdire les téléphones pendant les cours","Filmer tous les cours","Distribuer des ordinateurs aux étudiants"],"a":1,"why":"El texto dice que «certaines universités envisagent d'interdire purement et simplement les téléphones pendant les cours»."},{"q":"Selon les partisans de l'interdiction, l'étudiant distrait…","o":["gêne aussi les autres étudiants","finit toujours par abandonner ses études","obtient de meilleures notes avec son téléphone"],"a":0,"why":"«Il détourne aussi l'attention de ses voisins»: su distracción afecta también a los demás."},{"q":"Dans le texte, « contre-productive » signifie :","o":["trop coûteuse","contraire à la loi","qui produit l'effet inverse de celui recherché","difficile à expliquer"],"a":2,"why":"Algo «contre-productif» obtiene lo contrario de lo que busca: prohibir el teléfono quitaría también una herramienta de trabajo y renunciaría a educar."},{"q":"Quelle est la position de l'autrice ?","o":["Elle soutient l'interdiction totale","Elle veut interdire aussi les ordinateurs","Elle n'exprime aucune opinion personnelle","Elle s'oppose à l'interdiction et propose de changer la pédagogie"],"a":3,"why":"Escribe «une interdiction totale me paraît à la fois naïve et contre-productive» y propone «repenser nos cours»."},{"q":"Quelle est l'intention de la question finale (« Et si le problème n'était pas le téléphone… ») ?","o":["Provoquer une remise en question chez les enseignants","Se moquer des étudiants distraits","Annoncer une nouvelle loi"],"a":0,"why":"Es una pregunta retórica: invita a los profesores («notre façon d'enseigner») a cuestionar sus propios métodos."}],"voice":"f"},{"id":"r-b2-2","level":"B2","title":"Le surtourisme, rançon du succès","theme":"Turismo responsable","emoji":"🧳","intro":"Venecia, Barcelona… y también Cartagena: cuando el turismo masivo transforma la vida de los habitantes.","text":"Des ruelles si pleines qu'on ne peut plus y marcher, des loyers qui explosent, des habitants qui quittent leur quartier : dans de nombreuses villes, le tourisme est devenu victime de son propre succès. On appelle ce phénomène le surtourisme.\n\nÀ Venise, le nombre de résidents du centre historique a été divisé par plus de trois en quelques décennies, tandis que des millions de visiteurs y débarquent chaque année. Depuis 2024, les touristes qui viennent passer une seule journée doivent même payer un droit d'entrée certains jours. Barcelone, Amsterdam ou Dubrovnik ont, elles aussi, adopté des mesures pour limiter les locations de courte durée ou les bateaux de croisière.\n\nLa Colombie n'est pas épargnée. À Carthagène, le centre colonial se transforme peu à peu en décor : les maisons familiales deviennent des hôtels de charme, et les commerces de proximité cèdent la place aux boutiques de souvenirs. Beaucoup d'habitants de Getsemaní, quartier autrefois populaire, n'ont plus les moyens d'y vivre.\n\nFaut-il pour autant cesser de voyager ? Évidemment pas. Le tourisme fait vivre des millions de personnes et favorise les rencontres entre cultures. Mais voyager de façon responsable suppose quelques gestes simples : partir hors saison, préférer les logements tenus par des habitants, consommer local et, surtout, se souvenir qu'on visite le lieu de vie de quelqu'un d'autre, pas un parc d'attractions.","gloss":[["ruelles","callejuelas"],["des loyers","arriendos, alquileres"],["surtourisme","sobreturismo, turismo masivo"],["tandis que","mientras que"],["débarquent","desembarcan, llegan en masa"],["un droit d'entrée","una tarifa de entrada"],["locations de courte durée","alquileres de corta duración"],["épargnée","a salvo, librada"],["cèdent la place","ceden el lugar"],["autrefois","antiguamente, antes"],["n'ont plus les moyens","ya no tienen con qué pagar"],["pour autant","por ello, por eso"],["hors saison","en temporada baja"]],"questions":[{"q":"D'après le texte, qu'est-ce que le surtourisme ?","o":["Un tourisme de luxe réservé aux riches","Un afflux touristique si important qu'il nuit à la vie des habitants","Le fait de voyager hors saison"],"a":1,"why":"El primer párrafo describe calles saturadas, alquileres que explotan y habitantes que se van: el turismo «victime de son propre succès»."},{"q":"Quelle mesure Venise a-t-elle prise ?","o":["Interdire les bateaux de croisière dans tout le pays","Fermer son centre historique aux étrangers","Obliger les touristes à dormir sur place","Faire payer un droit d'entrée aux visiteurs d'un jour, certains jours"],"a":3,"why":"«Les touristes qui viennent passer une seule journée doivent même payer un droit d'entrée certains jours»."},{"q":"Dans « La Colombie n'est pas épargnée », « épargnée » signifie :","o":["à l'abri du problème","économe","célèbre","favorisée"],"a":0,"why":"Aquí «épargner» significa «librar de algo malo»: Colombia no se libra del sobreturismo. (El otro sentido, «ahorrar», no encaja)."},{"q":"Que suggère l'expression « se transforme peu à peu en décor » ?","o":["Qu'on tourne beaucoup de films à Carthagène","Qu'on rénove les maisons pour les habitants","Que le centre perd sa vie authentique et devient une façade pour touristes"],"a":2,"why":"Un «décor» es una escenografía: el centro sigue bonito, pero pierde sus habitantes y comercios de barrio."},{"q":"Quelle est l'intention de l'auteur dans le dernier paragraphe ?","o":["Encourager un tourisme plus responsable sans renoncer au voyage","Décourager toute forme de voyage","Faire la publicité des hôtels de charme"],"a":0,"why":"Responde «Évidemment pas» a la idea de dejar de viajar y propone «quelques gestes simples» para viajar de forma responsable."}],"voice":"m"},{"id":"r-b2-3","level":"B2","title":"Au Québec, le français se défend","theme":"Francofonía y lengua","emoji":"⚜️","intro":"¿Por qué en Quebec se protege el francés por ley? Un texto sobre identidad, política lingüística… y anglicismos.","text":"Au Québec, le français n'est pas seulement une langue : c'est un symbole d'identité et, pour beaucoup, un combat. Entourés de plus de 350 millions d'anglophones en Amérique du Nord, les quelque sept millions de Québécois francophones savent que leur langue ne survivra pas sans effort.\n\nC'est dans cet esprit qu'a été adoptée, en 1977, la Charte de la langue française, plus connue sous le nom de « loi 101 ». Elle fait du français la langue officielle de la province et impose son usage dans le travail, le commerce et l'affichage public. Elle oblige également la plupart des enfants d'immigrants à fréquenter l'école en français. Grâce à cette loi, des générations de nouveaux arrivants, venus d'Haïti, du Maghreb ou d'Amérique latine, ont adopté le français comme langue commune.\n\nCette politique suscite toutefois des critiques. Certains anglophones de Montréal s'estiment traités comme des citoyens de seconde zone ; des entreprises se plaignent de contraintes administratives. Les défenseurs de la loi répondent qu'une langue minoritaire, sans protection, finit toujours par céder devant la langue dominante.\n\nLe débat se joue aussi sur le terrain du vocabulaire. Là où un Français dira volontiers « faire du shopping » ou « envoyer un mail », un Québécois préférera « magasiner » et « envoyer un courriel ». Ironie de l'histoire : c'est souvent au Québec qu'on défend le plus ardemment la langue de Molière contre les anglicismes.","gloss":[["un combat","una lucha"],["Entourés de","rodeados de"],["survivra","sobrevivirá"],["dans cet esprit","con ese propósito, en ese espíritu"],["l'affichage public","los avisos y letreros públicos"],["fréquenter l'école","asistir a la escuela"],["nouveaux arrivants","recién llegados, inmigrantes"],["toutefois","sin embargo"],["de seconde zone","de segunda categoría"],["se plaignent","se quejan"],["céder devant","ceder ante"],["magasiner","ir de compras (quebequismo)"],["un courriel","un correo electrónico (palabra creada en Quebec)"],["ardemment","con ardor, fervientemente"]],"questions":[{"q":"Pourquoi les Québécois estiment-ils que leur langue doit être protégée ?","o":["Parce que le français est interdit ailleurs au Canada","Parce qu'ils forment une minorité entourée d'anglophones","Parce que leur accent est mal compris en France"],"a":1,"why":"Están «entourés de plus de 350 millions d'anglophones» y saben que su lengua «ne survivra pas sans effort»."},{"q":"Que prévoit la loi 101 pour la plupart des enfants d'immigrants ?","o":["Ils doivent aller à l'école en français","Ils peuvent choisir librement leur école","Ils doivent d'abord apprendre l'anglais","Ils sont exemptés de cours de langue"],"a":0,"why":"«Elle oblige également la plupart des enfants d'immigrants à fréquenter l'école en français»."},{"q":"Quelle critique est adressée à cette politique ?","o":["Elle coûte trop cher aux écoles","Elle interdit l'anglais à la maison","Certains anglophones se sentent traités comme des citoyens de seconde zone"],"a":2,"why":"«Certains anglophones de Montréal s'estiment traités comme des citoyens de seconde zone»."},{"q":"Au Québec, « magasiner » veut dire :","o":["travailler dans un magasin","faire du shopping","ranger des marchandises","ouvrir une boutique"],"a":1,"why":"El texto opone el francés de Francia «faire du shopping» al quebequense «magasiner»."},{"q":"Quel est le ton de la dernière phrase (« Ironie de l'histoire… ») ?","o":["Légèrement ironique : l'auteur s'amuse de ce paradoxe","Indigné contre les Français","Tragique et pessimiste"],"a":0,"why":"El autor señala con humor una paradoja: es en Quebec, y no en Francia, donde más se defiende el francés frente a los anglicismos."}],"voice":"f"},{"id":"r-b2-4","level":"B2","title":"Les traducteurs face à la machine","theme":"Inteligencia artificial","emoji":"🤖","intro":"¿Van a desaparecer los traductores con la inteligencia artificial? Un tema que toca de cerca a los futuros licenciados en lenguas.","text":"« À quoi bon apprendre les langues, puisque les machines traduisent tout ? » Cette question, les étudiants en langues l'entendent de plus en plus souvent. Il est vrai que les outils de traduction automatique, alimentés par l'intelligence artificielle, ont fait des progrès spectaculaires : en quelques secondes, ils produisent des textes souvent corrects et parfois même élégants.\n\nFaut-il pour autant annoncer la fin des traducteurs ? Les professionnels sont plus nuancés. Selon eux, la machine excelle dans les textes standardisés — modes d'emploi, courriels commerciaux — mais trébuche dès que le sens dépend du contexte. Un jeu de mots, une allusion culturelle, un registre ironique : autant de pièges qu'un algorithme ne détecte pas toujours. Or, une erreur dans un contrat, une notice médicale ou un discours diplomatique peut coûter très cher.\n\nLe métier, en réalité, se transforme. De plus en plus de traducteurs pratiquent la « post-édition » : ils corrigent et améliorent un premier jet produit par la machine. D'autres se spécialisent dans des domaines où la créativité est essentielle, comme la littérature, le sous-titrage ou l'adaptation publicitaire.\n\nPour les futurs diplômés, le message est clair : il ne suffit plus de connaître deux langues. Il faut maîtriser les outils numériques, acquérir une solide culture générale et, surtout, cultiver ce que la machine n'a pas : le jugement, la sensibilité et la capacité à comprendre ce qu'un texte veut vraiment dire. Loin d'être condamnés, les linguistes de demain seront peut-être plus indispensables que jamais.","gloss":[["À quoi bon","¿de qué sirve…?"],["alimentés par","impulsados por"],["nuancés","matizados, moderados"],["excelle","sobresale, es excelente"],["modes d'emploi","manuales de instrucciones"],["trébuche","tropieza"],["dès que","en cuanto, tan pronto como"],["Un jeu de mots","un juego de palabras"],["autant de pièges","otras tantas trampas"],["Or,","ahora bien,"],["un premier jet","un primer borrador"],["le sous-titrage","el subtitulado"],["il ne suffit plus de","ya no basta con"],["Loin d'être","lejos de estar"]],"questions":[{"q":"Selon les professionnels, dans quels textes la machine est-elle la plus performante ?","o":["Les jeux de mots","Les textes standardisés, comme les modes d'emploi","Les discours diplomatiques","Les romans"],"a":1,"why":"«La machine excelle dans les textes standardisés — modes d'emploi, courriels commerciaux»."},{"q":"Dans le texte, « trébuche » signifie que la machine :","o":["refuse de traduire","traduit plus vite","commet des erreurs"],"a":2,"why":"«Trébucher» (tropezar) se usa aquí en sentido figurado: la máquina se equivoca cuando el sentido depende del contexto."},{"q":"En quoi consiste la « post-édition » ?","o":["À corriger et améliorer une traduction produite par la machine","À publier un livre après sa traduction","À traduire des sous-titres de films"],"a":0,"why":"Los traductores «corrigent et améliorent un premier jet produit par la machine»."},{"q":"Pourquoi l'auteur cite-t-il un contrat, une notice médicale ou un discours diplomatique ?","o":["Pour montrer que ce sont des textes faciles à traduire","Pour montrer qu'une erreur de traduction peut avoir des conséquences graves","Pour conseiller aux étudiants de devenir avocats","Pour critiquer les diplomates"],"a":1,"why":"Justo después dice que un error en ellos «peut coûter très cher»: son ejemplos de textos donde el riesgo es alto."},{"q":"Quelle est l'attitude de l'auteur face à l'avenir des linguistes ?","o":["Résolument pessimiste","Indifférente","Optimiste, mais consciente des changements nécessaires"],"a":2,"why":"Reconoce que «le métier se transforme» y que hay que adaptarse, pero concluye que los lingüistas serán «peut-être plus indispensables que jamais»."}],"voice":"m"},{"id":"r-c1-1","level":"C1","title":"Le cahier bleu","theme":"Cuento original","emoji":"📘","intro":"Un cuento original: una estudiante bogotana recién llegada a París encuentra un cuaderno olvidado en su estudio. Fíjate en el uso del passé simple.","text":"Le jour où Inés emménagea dans le petit studio de la rue des Envierges, à Belleville, elle ne remarqua pas tout de suite le cahier. Il était glissé derrière le radiateur, recouvert d'une poussière si épaisse qu'on l'aurait cru là depuis toujours. Ce n'est qu'en décembre, lorsque le chauffage refusa obstinément de s'allumer, qu'elle le découvrit en tâtonnant.\n\nLa couverture, d'un bleu délavé, ne portait aucun nom. À l'intérieur, une écriture penchée, serrée, alternait l'espagnol et le français, parfois dans la même phrase. « 14 mars 1974. Il pleut sur Paris comme il pleuvait sur Bogotá, mais ici, personne ne connaît mon nom. » Inés sentit sa gorge se nouer. Elle aussi était arrivée de Bogotá, un automne, avec deux valises et la conviction un peu naïve que Paris l'attendait.\n\nElle lut tout, d'une traite. L'inconnu — ou l'inconnue, car rien ne permettait de trancher — racontait ses nuits à faire la plonge dans un restaurant du boulevard, ses cours du soir à la Sorbonne, la solitude des dimanches, puis, peu à peu, les premières amitiés, un bal au bord du canal, une langue qui cessait d'être un mur pour devenir une maison. La dernière page ne comportait qu'une phrase : « Celui ou celle qui trouvera ce cahier saura que l'exil aussi peut devenir une patrie. »\n\nInés referma le cahier et resta longtemps immobile, le front contre la vitre froide. Dehors, la ville s'allumait fenêtre après fenêtre. Pour la première fois depuis son arrivée, elle ne se sentait pas étrangère : quelqu'un, cinquante ans plus tôt, avait marché dans les mêmes rues, douté des mêmes choses, et avait fini par y trouver sa place.\n\nLe lendemain, elle acheta un cahier neuf. Il était bleu, lui aussi.","gloss":[["emménagea","se mudó, se instaló (passé simple de emménager)"],["glissé","metido, deslizado"],["en tâtonnant","a tientas"],["délavé","desteñido"],["serrée","apretada (letra pequeña y junta)"],["sa gorge se nouer","que se le hacía un nudo en la garganta"],["d'une traite","de un tirón, sin parar"],["trancher","decidir, zanjar"],["faire la plonge","lavar platos en un restaurante (familiar)"],["cessait d'être","dejaba de ser"],["ne comportait qu'une phrase","solo contenía una frase"],["l'exil","el exilio"],["la vitre","el vidrio (de la ventana)"],["douté","dudado"]],"questions":[{"q":"Dans quelles circonstances Inés découvre-t-elle le cahier ?","o":["Le propriétaire le lui remet à son arrivée","Elle le trouve en cherchant derrière le radiateur, qui ne fonctionne pas","Elle le trouve dans une bibliothèque de la Sorbonne","Elle le reçoit par la poste"],"a":1,"why":"«Lorsque le chauffage refusa obstinément de s'allumer, […] elle le découvrit en tâtonnant»: estaba «glissé derrière le radiateur»."},{"q":"Pourquoi la première phrase du cahier bouleverse-t-elle Inés ?","o":["Elle reconnaît l'écriture d'un membre de sa famille","Elle déteste la pluie parisienne","Elle vient elle aussi de Bogotá et vit une expérience semblable"],"a":2,"why":"Justo después: «Elle aussi était arrivée de Bogotá»; se identifica con la soledad del autor del cuaderno."},{"q":"« rien ne permettait de trancher » signifie qu'on ne pouvait pas savoir :","o":["si l'auteur était un homme ou une femme","en quelle année le cahier avait été écrit","dans quelle langue le cahier était rédigé","où l'auteur habitait"],"a":0,"why":"La frase explica la duda «L'inconnu — ou l'inconnue»: nada permitía decidir el género de quien escribió."},{"q":"Que signifie l'image « une langue qui cessait d'être un mur pour devenir une maison » ?","o":["L'auteur du cahier travaillait dans le bâtiment","Le français, d'abord obstacle, devient un lieu où l'on se sent chez soi","L'auteur refuse finalement d'apprendre le français"],"a":1,"why":"Metáfora: el «mur» separa y excluye; la «maison» acoge. La lengua pasa de barrera a refugio."},{"q":"Que suggère la dernière phrase du récit ?","o":["Inés veut jeter le vieux cahier","Inés va rentrer en Colombie","Inés va collectionner des cahiers anciens","Inés va à son tour écrire son expérience, comme l'inconnu avant elle"],"a":3,"why":"Compra un cuaderno nuevo, «bleu, lui aussi»: el paralelismo sugiere que continuará la cadena y escribirá su propio exilio."}],"voice":"f"},{"id":"r-c1-2","level":"C1","title":"L'écriture inclusive : une querelle de points","theme":"Debate lingüístico","emoji":"✒️","intro":"Un debate que divide a Francia: la escritura inclusiva. Identifica los argumentos de cada bando y la postura del autor.","text":"Rarement une question de typographie aura autant enflammé la société française. L'écriture inclusive — dont la manifestation la plus visible est le point médian, comme dans « les étudiant·es » — divise depuis des années linguistes, enseignants, responsables politiques et simples citoyens.\n\nSes défenseurs partent d'un constat : la règle scolaire selon laquelle « le masculin l'emporte sur le féminin » n'a rien de naturel. Elle a été imposée par des grammairiens à partir du XVIIe siècle, parfois au nom d'arguments ouvertement sexistes. Or, la langue façonne nos représentations : des expériences de psycholinguistique montrent que, face à un mot comme « chercheurs », beaucoup de lecteurs imaginent spontanément des hommes. Rendre les femmes visibles dans la langue serait donc une manière de combattre les inégalités.\n\nLeurs adversaires dénoncent une pratique qui compliquerait inutilement la lecture, notamment pour les enfants ou les personnes dyslexiques, et qui serait impossible à prononcer. L'Académie française est allée jusqu'à parler, en 2017, de « péril mortel » pour la langue, et une circulaire ministérielle a proscrit en 2021 le point médian à l'école.\n\nEntre ces deux camps, de nombreux linguistes rappellent que l'écriture inclusive ne se réduit pas au point médian. Elle recouvre aussi des procédés bien moins polémiques : la féminisation des noms de métiers — « autrice », « ingénieure » —, les doublets comme « celles et ceux », ou l'emploi de termes épicènes tels que « le personnel » ou « les membres ». Plusieurs de ces usages, adoptés par la presse, ne choquent déjà plus personne.\n\nAu fond, cette querelle en dit sans doute davantage sur notre rapport à la norme que sur la grammaire elle-même. Une langue n'est jamais figée : elle évolue au gré des usages, et ce sont en définitive ses locuteurs, bien plus que les institutions, qui en décident.","gloss":[["enflammé","encendido, inflamado"],["le point médian","el punto medio (·)"],["l'emporte sur","prevalece sobre"],["ouvertement","abiertamente"],["façonne","moldea, da forma a"],["Leurs adversaires","sus opositores"],["péril mortel","peligro mortal"],["a proscrit","prohibió, proscribió"],["ne se réduit pas au","no se reduce al"],["épicènes","epicenos (misma forma para ambos géneros)"],["Au fond","en el fondo"],["figée","fija, inmóvil"],["au gré des","al ritmo de, según"],["en définitive","en última instancia"]],"questions":[{"q":"D'après ses défenseurs, la règle « le masculin l'emporte sur le féminin » :","o":["remonte directement au latin","a été imposée par des grammairiens à partir du XVIIe siècle","a été créée par l'Académie française en 2017"],"a":1,"why":"«Elle a été imposée par des grammairiens à partir du XVIIe siècle»: no es «naturelle», sino una norma histórica."},{"q":"Sur quel type d'argument les défenseurs s'appuient-ils pour affirmer que la langue façonne nos représentations ?","o":["Des statistiques sur l'emploi des femmes","Des témoignages d'enseignants","Des expériences de psycholinguistique","Des textes littéraires du XVIIe siècle"],"a":2,"why":"«Des expériences de psycholinguistique montrent que, face à un mot comme « chercheurs », beaucoup de lecteurs imaginent spontanément des hommes»."},{"q":"Lequel de ces arguments n'est PAS avancé par les adversaires ?","o":["Le point médian coûte trop cher à imprimer","Il complique la lecture pour les enfants","Il est difficile, voire impossible, à prononcer","Il gêne les personnes dyslexiques"],"a":0,"why":"El texto menciona la lectura difícil (niños, dislexia) y la imposibilidad de pronunciarlo, pero nunca un argumento económico."},{"q":"Des « termes épicènes » sont des mots :","o":["récemment inventés par les féministes","d'origine grecque","qui gardent la même forme pour désigner des hommes et des femmes"],"a":2,"why":"Los ejemplos «le personnel» o «les membres» designan a personas de cualquier sexo sin cambiar de forma."},{"q":"Quelle position l'auteur adopte-t-il dans sa conclusion ?","o":["Il défend fermement le point médian","Il demande à l'Académie de trancher définitivement","Il condamne toute forme d'écriture inclusive","Il prend du recul : l'usage des locuteurs finira par décider"],"a":3,"why":"Concluye de forma matizada: la lengua «évolue au gré des usages» y son «ses locuteurs, bien plus que les institutions, qui en décident»."}],"voice":"m"},{"id":"r-c1-3","level":"C1","title":"Aimé Césaire et la négritude","theme":"Literatura francófona","emoji":"🌺","intro":"Cómo dos estudiantes, un martiniqués y un senegalés, fundaron en París uno de los movimientos literarios más importantes del siglo XX.","text":"En 1931, un jeune Martiniquais de dix-huit ans débarque à Paris pour préparer le concours de l'École normale supérieure. Il s'appelle Aimé Césaire. Au lycée Louis-le-Grand, il se lie d'amitié avec un Sénégalais un peu plus âgé, Léopold Sédar Senghor. Avec le Guyanais Léon-Gontran Damas, ils vont donner naissance à l'un des mouvements intellectuels les plus marquants du XXe siècle : la négritude.\n\nLe mot, forgé par Césaire lui-même, est une provocation. En reprenant à son compte le terme « nègre », employé comme une insulte par les colonisateurs, il en renverse la charge : ce qui devait humilier devient une revendication de fierté. Face à une idéologie coloniale qui prétendait « civiliser » des peuples supposés sans histoire, les jeunes étudiants affirment la richesse des cultures africaines et la dignité de leurs héritiers, dispersés par la traite jusqu'aux Antilles et aux Amériques.\n\nEn 1939 paraît le texte fondateur du mouvement, le Cahier d'un retour au pays natal, long poème où la violence du réquisitoire se mêle à une inventivité verbale fulgurante. Paradoxe fécond : c'est dans la langue du colonisateur, qu'il plie à ses propres rythmes, que Césaire dénonce la colonisation.\n\nLes chemins des deux amis divergeront pourtant. Senghor deviendra en 1960 le premier président du Sénégal indépendant, puis le premier Africain élu à l'Académie française. Césaire, lui, restera fidèle à la Martinique, dont il sera député et maire de Fort-de-France pendant plus d'un demi-siècle.\n\nLa négritude n'a pas échappé aux critiques : certains, comme le Nigérian Wole Soyinka, lui ont reproché d'enfermer l'identité noire dans une essence figée. Il n'en demeure pas moins qu'elle a ouvert la voie aux littératures francophones contemporaines, en prouvant que le français pouvait devenir une langue de libération.","gloss":[["débarque","llega, desembarca"],["le concours","el examen de admisión (por oposición)"],["il se lie d'amitié","traba amistad"],["donner naissance à","dar origen a"],["forgé","acuñado, forjado"],["En reprenant à son compte","apropiándose de"],["il en renverse la charge","invierte su carga (su sentido negativo)"],["une revendication","una reivindicación"],["la traite","la trata de esclavos"],["réquisitoire","requisitoria, acusación"],["fulgurante","deslumbrante, fulgurante"],["qu'il plie","que doblega, que adapta"],["Il n'en demeure pas moins","no por ello deja de ser cierto (que)"],["ouvert la voie","abierto el camino"]],"questions":[{"q":"Où Césaire et Senghor se sont-ils rencontrés ?","o":["À Dakar, pendant l'indépendance","À Fort-de-France","Au lycée Louis-le-Grand, à Paris","À l'Académie française"],"a":2,"why":"«Au lycée Louis-le-Grand, il se lie d'amitié avec un Sénégalais un peu plus âgé, Léopold Sédar Senghor»."},{"q":"En quoi le mot « négritude » est-il une provocation ?","o":["Il transforme une insulte coloniale en motif de fierté","Il ridiculise la culture française","Il était interdit par la loi à l'époque"],"a":0,"why":"Césaire retoma la palabra insultante y «en renverse la charge : ce qui devait humilier devient une revendication de fierté»."},{"q":"Quel est le « paradoxe fécond » évoqué dans le troisième paragraphe ?","o":["Césaire écrit un poème en prose","Césaire dénonce la colonisation dans la langue même du colonisateur","Césaire critique Senghor tout en restant son ami"],"a":1,"why":"«C'est dans la langue du colonisateur, qu'il plie à ses propres rythmes, que Césaire dénonce la colonisation»: la paradoja resulta productiva."},{"q":"Dans le dernier paragraphe, « Il n'en demeure pas moins que » introduit :","o":["une hypothèse sur l'avenir","une conséquence de la critique de Soyinka","une opposition totale à la négritude","une concession : malgré les critiques, l'apport du mouvement reste indéniable"],"a":3,"why":"El conector reconoce las críticas pero afirma que, aun así, la négritude «a ouvert la voie aux littératures francophones contemporaines»."},{"q":"Comment caractériser le ton général du texte ?","o":["Informatif et plutôt élogieux, sans occulter les critiques","Polémique et hostile au mouvement","Neutre et purement chronologique, sans jugement","Ironique envers les deux poètes"],"a":0,"why":"El texto informa con datos, valora el movimiento («l'un des […] plus marquants», «fulgurante») y menciona también las críticas de Soyinka."}],"voice":"m"}];
window.__SIM=[{"id":"delf-b1","level":"B1","title":"Simulacro DELF B1","desc":"Examen completo de nivel B1: comprensión oral y escrita, producción escrita y oral sobre temas de la vida universitaria.","co":[{"title":"Document 1 — Une conversation entre étudiants","intro":"Escucharás el documento dos veces. Lee primero las preguntas y luego responde.","script":[["M","Salut Camila ! Tu as vu l'affiche dans le couloir ? L'association Terre Solidaire cherche des bénévoles pour le mois prochain."],["F","Oui, je l'ai vue. C'est pour aider dans une école à la campagne, non ?"],["M","Exactement. Il s'agit de donner des cours de soutien aux enfants le samedi matin. Ils organisent aussi un atelier de jardinage avec les familles."],["F","Ça a l'air génial, mais je ne sais pas si j'aurai le temps. Je travaille déjà dans une librairie le samedi après-midi."],["M","Justement, les activités se terminent à midi. Et c'est l'association qui paie le bus, donc ça ne coûte rien."],["F","Ah bon ? Dans ce cas, c'est possible. Il faut s'inscrire où ?"],["M","Sur leur site Internet, avant vendredi. Il y a aussi une réunion d'information mercredi à dix-huit heures, dans la salle deux cent quatre."],["F","Parfait. On y va ensemble ? Comme ça, je poserai mes questions directement."],["M","D'accord. Je t'attends devant la bibliothèque à dix-sept heures quarante-cinq."]],"questions":[{"q":"Que propose l'association Terre Solidaire ?","o":["Donner des cours de soutien à des enfants","Construire une école à la campagne","Vendre des livres pour une école"],"a":0,"why":"El chico dice: «Il s'agit de donner des cours de soutien aux enfants le samedi matin»."},{"q":"Pourquoi Camila hésite-t-elle d'abord ?","o":["Elle n'aime pas travailler avec des enfants","Elle travaille le samedi après-midi","Le transport est trop cher"],"a":1,"why":"Camila explica que ya trabaja en una librería el sábado por la tarde."},{"q":"Qui paie le transport ?","o":["Les étudiants","L'université","L'association"],"a":2,"why":"«C'est l'association qui paie le bus, donc ça ne coûte rien»."},{"q":"Quand a lieu la réunion d'information ?","o":["Mercredi à 18 h","Vendredi à 18 h","Samedi à midi"],"a":0,"why":"La reunión es «mercredi à dix-huit heures». El viernes es la fecha límite de inscripción."},{"q":"Où les deux étudiants vont-ils se retrouver ?","o":["Dans la salle 204","Devant la bibliothèque","À la librairie"],"a":1,"why":"Se encuentran «devant la bibliothèque» a las 17:45, antes de ir a la sala 204."}]},{"title":"Document 2 — Une émission de radio","intro":"Escucharás el documento dos veces. Lee primero las preguntas y luego responde.","script":[["F","Bonjour à tous et bienvenue dans Campus Info. Aujourd'hui, nous recevons Julien Moreau, responsable du nouveau service de vélos de l'université. Julien, bonjour."],["M","Bonjour, et merci de m'avoir invité."],["F","Alors, comment fonctionne ce service ?"],["M","C'est très simple. Depuis lundi, cinquante vélos sont disponibles dans trois stations : à l'entrée principale, devant la résidence étudiante et près du restaurant universitaire. Il suffit de télécharger l'application et de scanner sa carte d'étudiant."],["F","Et c'est payant ?"],["M","La première demi-heure est gratuite. Ensuite, cela coûte deux mille pesos par heure. Nous voulons surtout encourager les trajets courts."],["F","Quel est l'objectif principal du projet ?"],["M","Réduire l'utilisation des motos et des voitures sur le campus. Et nous espérons aussi que les étudiants feront un peu plus de sport !"],["F","Et si un vélo est abîmé ?"],["M","On le signale dans l'application, et un technicien passe dans la journée pour le réparer."],["F","Merci Julien. Et bonne route à tous nos auditeurs !"]],"questions":[{"q":"Depuis quand le service fonctionne-t-il ?","o":["Depuis lundi","Depuis le mois dernier","Depuis ce matin"],"a":0,"why":"Julien dice: «Depuis lundi, cinquante vélos sont disponibles»."},{"q":"Combien de stations y a-t-il ?","o":["Deux","Trois","Cinquante"],"a":1,"why":"Hay tres estaciones: la entrada principal, la residencia y el restaurante. Cincuenta es el número de bicicletas."},{"q":"Que faut-il pour utiliser un vélo ?","o":["Payer une inscription annuelle","L'application et la carte d'étudiant","Une autorisation d'un professeur"],"a":1,"why":"«Il suffit de télécharger l'application et de scanner sa carte d'étudiant»."},{"q":"Quel est l'objectif principal du projet ?","o":["Gagner de l'argent pour l'université","Réduire l'usage des motos et des voitures","Organiser des compétitions sportives"],"a":1,"why":"El objetivo principal es «réduire l'utilisation des motos et des voitures sur le campus»; el deporte es un objetivo secundario."},{"q":"Que faut-il faire si un vélo est abîmé ?","o":["Le rapporter à la résidence","Le signaler dans l'application","Appeler la radio"],"a":1,"why":"«On le signale dans l'application» y un técnico pasa ese mismo día."}]}],"ce":[{"title":"Texte 1 — Semaine de la francophonie","source":"Annonce publiée sur le site de l'université","text":"Semaine de la francophonie : participez !\n\nDu 15 au 19 mars, le département de langues étrangères organise sa traditionnelle Semaine de la francophonie. Au programme : projections de films québécois et sénégalais, atelier de cuisine haïtienne, concours de poésie et soirée de chansons françaises.\n\nLe concours de poésie est ouvert à tous les étudiants de l'université, quel que soit leur niveau de français. Les textes, de vingt lignes maximum, doivent être envoyés avant le 1er mars par courriel au secrétariat du département. Le gagnant recevra un dictionnaire bilingue et un abonnement d'un an à une plateforme de films francophones.\n\nL'atelier de cuisine est limité à vingt participants : l'inscription y est obligatoire, auprès du secrétariat. Les autres activités sont gratuites et sans réservation.\n\nNous recherchons également des volontaires pour accueillir le public et décorer les salles. Si vous êtes intéressé(e), présentez-vous au bureau 12 le lundi ou le jeudi après-midi.","questions":[{"q":"Qui organise la Semaine de la francophonie ?","o":["Le département de langues étrangères","Une association québécoise","Le restaurant universitaire"],"a":0,"why":"Primer párrafo: «le département de langues étrangères organise…»."},{"q":"Pour participer au concours de poésie, il faut avoir un bon niveau de français.","o":["Vrai","Faux"],"a":1,"why":"Falso: el concurso está abierto «quel que soit leur niveau de français» (sin importar el nivel)."},{"q":"Quelle est la date limite pour envoyer un poème ?","o":["Le 15 mars","Le 1er mars","Le 19 mars"],"a":1,"why":"Los textos deben enviarse «avant le 1er mars»."},{"q":"Que gagnera le vainqueur du concours ?","o":["Un voyage au Québec","Un dictionnaire et un abonnement à une plateforme de films","Un cours de cuisine"],"a":1,"why":"El ganador recibe «un dictionnaire bilingue et un abonnement d'un an à une plateforme de films francophones»."},{"q":"Pour quelle activité faut-il s'inscrire ?","o":["La soirée de chansons","Les projections de films","L'atelier de cuisine"],"a":2,"why":"Solo el taller de cocina requiere inscripción; las demás actividades son «sans réservation»."},{"q":"Les volontaires doivent se présenter au bureau 12 le mardi matin.","o":["Vrai","Faux"],"a":1,"why":"Falso: deben presentarse «le lundi ou le jeudi après-midi»."}]},{"title":"Texte 2 — Le sommeil des étudiants","source":"Article de magazine","text":"Étudiants : le sommeil, grand oublié de la réussite\n\nRévisions jusqu'à deux heures du matin, séries regardées « juste un épisode de plus », cours à sept heures : pour beaucoup d'étudiants, les nuits sont courtes. D'après les spécialistes, un jeune adulte a besoin de sept à neuf heures de sommeil par nuit. Or, dans de nombreuses universités, la moyenne se situe plutôt autour de six heures.\n\nLes conséquences sont connues : difficultés de concentration, irritabilité, baisse de la mémoire. « Beaucoup d'étudiants pensent qu'ils gagnent du temps en dormant moins, explique une médecin spécialiste du sommeil. En réalité, c'est pendant la nuit que le cerveau organise les informations apprises dans la journée. Réviser toute la nuit avant un examen est donc souvent contre-productif. »\n\nLes écrans jouent aussi un rôle important. La lumière des téléphones retarde l'endormissement, et les notifications réveillent parfois les étudiants en pleine nuit. Les spécialistes conseillent de poser son téléphone au moins une heure avant de se coucher et de garder des horaires réguliers, même le week-end.\n\nCertaines universités commencent à réagir. Quelques-unes ont décidé de ne plus programmer de cours avant huit heures ; d'autres proposent des ateliers pour apprendre à mieux gérer son temps. Les premiers résultats semblent encourageants : les étudiants qui y participent déclarent se sentir moins fatigués et plus motivés.\n\nDormir, finalement, n'est pas une perte de temps : c'est une partie du travail.","questions":[{"q":"Selon les spécialistes, de combien d'heures de sommeil un jeune adulte a-t-il besoin ?","o":["Six heures","De sept à neuf heures","Plus de dix heures"],"a":1,"why":"«Un jeune adulte a besoin de sept à neuf heures de sommeil par nuit». Seis horas es el promedio real de los estudiantes."},{"q":"D'après la médecin, pourquoi est-il déconseillé de réviser toute la nuit avant un examen ?","o":["Parce que le cerveau organise les connaissances pendant le sommeil","Parce que les bibliothèques sont fermées la nuit","Parce que les examens ont lieu l'après-midi"],"a":0,"why":"«C'est pendant la nuit que le cerveau organise les informations apprises dans la journée»."},{"q":"La lumière des téléphones aide à s'endormir plus vite.","o":["Vrai","Faux"],"a":1,"why":"Falso: la luz de los teléfonos «retarde l'endormissement» (retrasa el momento de dormirse)."},{"q":"Que conseillent les spécialistes ?","o":["Dormir beaucoup plus le week-end pour récupérer","Poser son téléphone une heure avant de se coucher","Étudier uniquement le matin"],"a":1,"why":"Aconsejan dejar el teléfono una hora antes de acostarse y mantener horarios regulares, incluso el fin de semana."},{"q":"Quelle mesure certaines universités ont-elles prise ?","o":["Supprimer les examens de fin d'année","Ne plus programmer de cours avant huit heures","Interdire les téléphones sur le campus"],"a":1,"why":"«Quelques-unes ont décidé de ne plus programmer de cours avant huit heures»."},{"q":"Quelle est l'idée principale de la conclusion ?","o":["Le sommeil fait partie du travail de l'étudiant","Les étudiants dorment trop","Les universités sont responsables de la fatigue"],"a":0,"why":"La frase final dice que dormir «n'est pas une perte de temps : c'est une partie du travail»."}]}],"pe":{"title":"Contribution à un forum","context":"En un foro de estudiantes francófonos se debate si, durante la universidad, es mejor vivir con los padres o de forma independiente. Participas contando tu experiencia y dando tu opinión argumentada.","consigne":"Sur un forum d'étudiants francophones, on pose la question suivante : « Pendant les études, vaut-il mieux habiter chez ses parents ou vivre de façon indépendante ? » Vous répondez en racontant votre expérience personnelle et en donnant votre opinion, illustrée d'exemples précis. (160 mots minimum)","min":160,"max":200},"po":{"title":"Monologue suivi — Le sport à l'université","doc":"","consigne":"Selon vous, la pratique d'un sport devrait-elle être obligatoire pour tous les étudiants universitaires ? Présentez votre opinion de façon claire et organisée, avec des arguments et des exemples tirés de votre expérience. L'examinateur pourra ensuite vous poser quelques questions.","consigne_es":"¿Debería ser obligatorio practicar un deporte para todos los estudiantes universitarios? Presenta tu opinión de forma clara y organizada, con argumentos y ejemplos de tu experiencia. Después el examinador te hará algunas preguntas.","prep_s":120,"talk_s":150,"tips":["Anota solo palabras clave durante la preparación, no frases completas.","Estructura: introducción con tu opinión, dos o tres argumentos con ejemplos, conclusión.","Usa conectores de opinión: «à mon avis», «il me semble que», «par contre», «c'est pourquoi»."]}},{"id":"delf-b2","level":"B2","title":"Simulacro DELF B2","desc":"Examen completo de nivel B2 con documentos auténticos modelados: entrevistas, debate, artículo de opinión, carta formal y defensa de un punto de vista.","co":[{"title":"Document 1 — Entretien : les jardins partagés","intro":"Escucharás el documento dos veces. Lee primero las preguntas y luego responde.","script":[["F","Vous écoutez Villes en transition. Mon invité aujourd'hui est Thomas Leroy, sociologue, qui étudie les jardins partagés depuis une dizaine d'années. Thomas Leroy, qu'est-ce qu'un jardin partagé, exactement ?"],["M","C'est un espace, souvent un terrain abandonné, que les habitants d'un quartier cultivent ensemble. On y fait pousser des légumes, des herbes aromatiques, parfois des fleurs. Mais contrairement à ce qu'on imagine, la production alimentaire n'est pas l'essentiel."],["F","Ah non ? Alors qu'est-ce qui motive les participants ?"],["M","Avant tout, le lien social. Dans les grandes villes, beaucoup de gens ne connaissent même pas leurs voisins. Le jardin devient un lieu de rencontre entre générations et entre cultures. J'ai vu des retraités apprendre à des adolescents à planter des tomates, et des familles immigrées partager des semences rapportées de leur pays d'origine."],["F","Est-ce qu'il y a aussi des difficultés ?"],["M","Bien sûr. Les désaccords sur l'organisation sont fréquents : qui arrose pendant les vacances, qui décide de ce qu'on plante… Et surtout, ces jardins sont fragiles, car les municipalités peuvent à tout moment récupérer les terrains pour y construire des logements."],["F","Que faudrait-il faire, selon vous ?"],["M","Les intégrer dans les plans d'urbanisme, pour leur garantir une existence à long terme. Ils coûtent très peu et rapportent énormément à la collectivité, en termes de cohésion sociale comme de qualité de vie."]],"questions":[{"q":"Selon Thomas Leroy, quel est le principal intérêt des jardins partagés ?","o":["Produire de la nourriture bon marché","Créer du lien social dans les quartiers","Embellir les terrains abandonnés"],"a":1,"why":"Dice que la producción de alimentos «n'est pas l'essentiel» y que lo que motiva es «avant tout, le lien social»."},{"q":"Quel exemple le sociologue donne-t-il ?","o":["Des retraités qui transmettent leur savoir à des adolescents","Des étudiants qui vendent leurs légumes","Des enfants qui organisent des fêtes de quartier"],"a":0,"why":"Menciona a jubilados que enseñan a adolescentes a sembrar tomates."},{"q":"Quelle difficulté interne mentionne-t-il ?","o":["Le manque d'eau","Les désaccords sur l'organisation","Le coût des semences"],"a":1,"why":"«Les désaccords sur l'organisation sont fréquents»: quién riega en vacaciones, qué se siembra…"},{"q":"Pourquoi ces jardins sont-ils fragiles ?","o":["Parce que les habitants s'en désintéressent vite","Parce que les villes peuvent récupérer les terrains","Parce que la pollution empêche les plantes de pousser"],"a":1,"why":"Los municipios pueden recuperar los terrenos para construir viviendas."},{"q":"Que propose-t-il pour l'avenir des jardins partagés ?","o":["Les intégrer dans les plans d'urbanisme","Les confier à des entreprises privées","Les réserver aux familles"],"a":0,"why":"Propone «les intégrer dans les plans d'urbanisme» para garantizar su existencia a largo plazo."}]},{"title":"Document 2 — Débat : la semaine de quatre jours","intro":"Escucharás el documento dos veces. Lee primero las preguntas y luego responde.","script":[["M","Bonsoir. Plusieurs entreprises expérimentent aujourd'hui la semaine de quatre jours, sans baisse de salaire. Pour en parler, j'accueille Claire Dubois, directrice d'une agence de communication qui l'a adoptée il y a deux ans. Claire Dubois, quel bilan en tirez-vous ?"],["F","Un bilan très positif. Nos salariés sont moins stressés, les arrêts maladie ont diminué de près de moitié et, contrairement à ce que je craignais, la productivité n'a pas baissé. Les réunions sont plus courtes, chacun s'organise mieux."],["M","Pourtant, certains économistes estiment que ce modèle ne peut pas fonctionner partout."],["F","Ils ont raison sur un point. Dans un hôpital ou dans un commerce, on ne peut pas simplement fermer un jour par semaine. Il faut alors organiser des roulements, ce qui demande davantage de personnel, et donc plus d'argent."],["M","Et vos clients, comment ont-ils réagi ?"],["F","Au début, certains étaient inquiets. Mais nous avons maintenu une permanence le vendredi, et aujourd'hui plus personne ne s'en plaint. D'ailleurs, cette organisation nous aide beaucoup à recruter : les jeunes diplômés sont très attachés à l'équilibre entre vie professionnelle et vie personnelle."],["M","Recommanderiez-vous ce modèle à d'autres entreprises ?"],["F","Oui, mais à condition de le préparer soigneusement, avec les équipes, et de l'adapter à chaque métier. Imposer la même formule à tout le monde serait une erreur."]],"questions":[{"q":"Depuis combien de temps l'agence de Claire Dubois applique-t-elle la semaine de quatre jours ?","o":["Six mois","Deux ans","Cinq ans"],"a":1,"why":"El presentador dice que la adoptó «il y a deux ans»."},{"q":"Quel effet a été observé sur les arrêts maladie ?","o":["Ils ont augmenté","Ils sont restés stables","Ils ont diminué de près de moitié"],"a":2,"why":"«Les arrêts maladie ont diminué de près de moitié»."},{"q":"Selon Claire Dubois, pourquoi ce modèle est-il difficile à appliquer dans un hôpital ?","o":["Parce que les médecins refusent de travailler moins","Parce qu'il faut plus de personnel pour organiser des roulements","Parce que la loi l'interdit"],"a":1,"why":"No se puede cerrar un día: hay que organizar turnos, lo que exige más personal y más dinero."},{"q":"Comment l'agence a-t-elle rassuré ses clients ?","o":["En baissant ses prix","En maintenant une permanence le vendredi","En travaillant le samedi"],"a":1,"why":"«Nous avons maintenu une permanence le vendredi»."},{"q":"Quel avantage supplémentaire la directrice mentionne-t-elle ?","o":["Le modèle facilite le recrutement","Le modèle réduit les impôts de l'entreprise","Le modèle attire des clients étrangers"],"a":0,"why":"«Cette organisation nous aide beaucoup à recruter» porque los jóvenes valoran el equilibrio vida laboral y personal."}]}],"ce":[{"title":"Texte — Et si l'on supprimait les notes ?","source":"Article de presse, rubrique Éducation","text":"Et si l'on supprimait les notes ?\n\nDe l'école primaire à l'université, la note — sur vingt en France, sur cinq dans les universités colombiennes — rythme la vie des élèves. Elle sert à mesurer les connaissances, à classer, à sélectionner. Pourtant, depuis quelques années, un nombre croissant d'enseignants et de chercheurs remettent en question ce système que l'on croyait immuable.\n\nLeur premier reproche concerne la fiabilité. Plusieurs expériences ont montré qu'une même copie, corrigée par différents professeurs, pouvait obtenir des notes très éloignées. L'ordre de correction, la fatigue du correcteur ou même l'écriture de l'élève influencent le résultat. La note, présentée comme objective, serait donc beaucoup plus arbitraire qu'il n'y paraît.\n\nLe second reproche est pédagogique. Pour de nombreux spécialistes des sciences de l'éducation, la note transforme l'apprentissage en compétition. Les élèves finissent par travailler pour obtenir un chiffre plutôt que pour comprendre. Pire encore, les mauvaises notes répétées découragent les plus fragiles, qui se persuadent qu'ils sont « nuls » et cessent tout effort.\n\nC'est pourquoi certains établissements expérimentent d'autres formes d'évaluation. Au lieu d'un chiffre, l'élève reçoit un bilan détaillé des compétences acquises, en cours d'acquisition ou à retravailler. L'erreur n'y est plus sanctionnée, mais analysée comme une étape normale de l'apprentissage. Les enseignants qui pratiquent cette méthode affirment que leurs élèves prennent davantage de risques et gagnent en autonomie.\n\nLes défenseurs de la note, eux, ne manquent pas d'arguments. Ils rappellent qu'elle est simple à comprendre, pour les élèves comme pour les parents, et qu'elle prépare au monde du travail, où chacun est également évalué. Ils craignent en outre que sa suppression ne profite surtout aux familles les plus favorisées, capables de décoder des appréciations complexes, tandis que les autres perdraient un repère clair. Enfin, les universités et les employeurs continuent d'exiger des résultats chiffrés pour comparer les candidats.\n\nEntre ces deux positions, une voie intermédiaire semble se dessiner : conserver des notes pour les examens finaux, mais multiplier, au cours de l'année, les évaluations formatives, sans enjeu, qui permettent à chacun de progresser à son rythme. La question n'est peut-être pas tant de supprimer la note que de lui rendre sa fonction première : aider l'élève à apprendre.","questions":[{"q":"Quel est le premier reproche adressé aux notes ?","o":["Elles coûtent trop cher aux établissements","Elles ne sont pas fiables","Elles sont incompréhensibles pour les parents"],"a":1,"why":"Segundo párrafo: «Leur premier reproche concerne la fiabilité»."},{"q":"Selon le texte, une même copie obtient toujours la même note, quel que soit le correcteur.","o":["Vrai","Faux"],"a":1,"why":"Falso: una misma copia corregida por distintos profesores puede obtener «des notes très éloignées»."},{"q":"D'après les spécialistes cités, quel effet les mauvaises notes répétées peuvent-elles avoir ?","o":["Elles poussent les élèves à travailler davantage","Elles découragent les élèves les plus fragiles","Elles rendent les élèves plus autonomes"],"a":1,"why":"«Les mauvaises notes répétées découragent les plus fragiles»."},{"q":"Dans les établissements sans notes, comment l'erreur est-elle considérée ?","o":["Comme une faute à sanctionner","Comme une étape normale de l'apprentissage","Comme le signe d'un manque de travail"],"a":1,"why":"El error es «analysée comme une étape normale de l'apprentissage»."},{"q":"Pourquoi certains craignent-ils que la suppression des notes soit injuste ?","o":["Parce que les familles favorisées décodent plus facilement les appréciations complexes","Parce que les professeurs devraient travailler davantage","Parce que les élèves n'aimeraient plus l'école"],"a":0,"why":"Temen que beneficie a las familias favorecidas, «capables de décoder des appréciations complexes»."},{"q":"Quelle solution intermédiaire l'article évoque-t-il ?","o":["Supprimer les examens finaux","Garder des notes finales et multiplier les évaluations formatives","Noter uniquement les élèves volontaires"],"a":1,"why":"Último párrafo: conservar notas en los exámenes finales y multiplicar las evaluaciones formativas."},{"q":"Quelle est la position de l'auteur en conclusion ?","o":["La note doit disparaître immédiatement","La note doit avant tout servir à aider l'élève à apprendre","Le système actuel ne doit pas changer"],"a":1,"why":"Propone «rendre [à la note] sa fonction première : aider l'élève à apprendre»."}]}],"pe":{"title":"Lettre formelle","context":"La biblioteca de tu universidad anunció que, por razones presupuestales, cerrará a las 5 p. m. y ya no abrirá los sábados. En nombre de la asociación de estudiantes, escribes una carta formal al director o directora de la universidad.","consigne":"La bibliothèque de votre université a annoncé qu'elle fermerait désormais à 17 heures et ne serait plus ouverte le samedi, pour des raisons budgétaires. Au nom de l'association des étudiants, vous écrivez une lettre au directeur ou à la directrice de l'université pour exprimer votre désaccord, exposer les conséquences de cette décision et proposer des solutions concrètes. (250 mots minimum)","min":250,"max":320},"po":{"title":"Point de vue — La publicité alimentaire et les enfants","doc":"Au Chili, depuis 2016, les aliments trop riches en sucre, en sel ou en graisses doivent porter des étiquettes noires d'avertissement, et leur publicité est interdite dans les programmes destinés aux enfants. La Colombie a adopté à son tour une loi sur l'étiquetage d'avertissement en 2021. Les associations de santé publique saluent ces mesures, qui auraient contribué à faire baisser la consommation de boissons sucrées. L'industrie agroalimentaire dénonce, elle, une atteinte à la liberté commerciale et rappelle que l'éducation alimentaire des enfants relève d'abord des familles.","consigne":"Dégagez le problème soulevé par ce document. Présentez ensuite votre opinion de manière argumentée et défendez-la face à l'examinateur : faut-il interdire la publicité pour les produits trop sucrés ou trop gras destinés aux enfants ?","consigne_es":"Identifica el problema que plantea el documento. Luego presenta tu opinión argumentada y defiéndela ante el examinador: ¿hay que prohibir la publicidad de productos demasiado azucarados o grasos dirigida a los niños?","prep_s":300,"talk_s":240,"tips":["Empieza con una frase que presente el tema y formule el problema como pregunta.","Anuncia tu plan y desarrolla dos o tres argumentos, cada uno con un ejemplo (Colombia, Chile, tu experiencia).","En el debate, reconoce los argumentos contrarios antes de refutarlos: «certes…, mais…».","Evita leer tus notas: mira al examinador y habla con naturalidad."]}},{"id":"dalf-c1","level":"C1","title":"Simulacro DALF C1","desc":"Examen completo de nivel C1: entrevista y conferencia largas, texto argumentativo complejo, ensayo y exposición oral con debate.","co":[{"title":"Document 1 — Entretien : les páramos, châteaux d'eau des Andes","intro":"Escucharás el documento dos veces. Lee primero las preguntas y luego responde.","script":[["F","Bonjour et bienvenue dans Planète en questions. Nous parlons aujourd'hui des páramos avec Andrés Rojas, écologue spécialiste des écosystèmes de haute montagne. Andrés Rojas, pour nos auditeurs qui ne les connaissent pas, qu'est-ce qu'un páramo ?"],["M","C'est un écosystème qu'on trouve dans les Andes, en général au-dessus de trois mille mètres d'altitude, entre la limite supérieure des forêts et les neiges éternelles. Il se caractérise par une végétation très particulière, notamment les frailejones, ces plantes aux feuilles duveteuses qui ne grandissent que d'environ un centimètre par an."],["F","On surnomme souvent les páramos les châteaux d'eau du pays. Pourquoi ?"],["M","Parce que leurs sols et leur végétation fonctionnent comme une gigantesque éponge. Ils captent l'humidité du brouillard et des pluies, puis la relâchent lentement, tout au long de l'année. Sans eux, les rivières qui alimentent de nombreuses villes andines connaîtraient des variations bien plus brutales, avec des crues à la saison des pluies et des pénuries à la saison sèche."],["F","Quelles sont les principales menaces qui pèsent sur eux ?"],["M","Il y en a trois, qui se combinent. D'abord, l'extension de l'agriculture et de l'élevage : la culture de la pomme de terre remonte de plus en plus haut. Ensuite, l'exploitation minière, qui peut contaminer les sources. Et enfin le réchauffement climatique, qui repousse les espèces vers les sommets, là où elles n'ont plus d'espace pour se déplacer."],["F","La loi interdit pourtant l'exploitation minière dans ces zones, non ?"],["M","En principe, oui. Mais la délimitation exacte des páramos reste contestée, et des familles paysannes y vivent depuis des générations. On ne peut pas simplement les expulser. Tout l'enjeu consiste à construire avec elles des modes de production compatibles avec la conservation, et à les rémunérer pour les services environnementaux qu'elles rendent à l'ensemble de la société."]],"questions":[{"q":"Comment l'écologue définit-il un páramo ?","o":["Une forêt tropicale de basse altitude","Un écosystème andin situé entre la limite des forêts et les neiges éternelles","Une zone désertique au sommet des volcans"],"a":1,"why":"Lo sitúa en los Andes, por encima de 3 000 m, «entre la limite supérieure des forêts et les neiges éternelles»."},{"q":"Pourquoi compare-t-on les páramos à des châteaux d'eau ?","o":["Parce qu'ils contiennent de grands lacs artificiels","Parce qu'ils absorbent l'humidité et la restituent progressivement","Parce qu'on y a construit de nombreux barrages"],"a":1,"why":"Funcionan como una esponja: captan la humedad y la liberan lentamente durante todo el año."},{"q":"Parmi les menaces citées, laquelle est explicitement liée à la contamination de l'eau ?","o":["L'exploitation minière","La culture de la pomme de terre","Le réchauffement climatique"],"a":0,"why":"Dice que la minería «peut contaminer les sources»."},{"q":"Quel effet du réchauffement climatique est mentionné ?","o":["Il fait disparaître les brouillards","Il repousse les espèces vers les sommets, où l'espace manque","Il accélère la croissance des frailejones"],"a":1,"why":"El calentamiento «repousse les espèces vers les sommets, là où elles n'ont plus d'espace»."},{"q":"Quelle solution Andrés Rojas privilégie-t-il pour les familles paysannes ?","o":["Les reloger en ville","Les associer à la conservation et rémunérer leurs services environnementaux","Leur interdire toute activité agricole"],"a":1,"why":"Propone construir con ellas modos de producción compatibles y remunerarlas por sus servicios ambientales; descarta expulsarlas."}]},{"title":"Document 2 — Conférence : le droit à l'erreur","intro":"Escucharás el documento dos veces. Lee primero las preguntas y luego responde.","script":[["F","Bonsoir à toutes et à tous. Pour ce troisième rendez-vous de notre cycle Apprendre autrement, nous accueillons Marc Delorme, chercheur en sciences cognitives. Son thème ce soir : le rôle de l'erreur dans l'apprentissage. Monsieur Delorme, la parole est à vous."],["M","Merci. Je voudrais commencer par une question simple : combien d'entre vous ont déjà eu honte de se tromper en classe ? Je vois beaucoup de mains levées, et c'est bien là le problème. Dans la plupart de nos systèmes éducatifs, l'erreur est perçue comme un échec, voire comme une faute morale. On la souligne en rouge, on la pénalise, et l'élève comprend très vite qu'il vaut mieux se taire que de risquer une mauvaise réponse."],["M","Or les recherches en neurosciences montrent exactement l'inverse. Le cerveau apprend en comparant ce qu'il avait prévu avec ce qui se produit réellement. C'est ce décalage, ce qu'on appelle le signal d'erreur, qui déclenche l'ajustement de nos connaissances. Autrement dit, sans erreur, il n'y a pas d'apprentissage."],["M","Cela ne signifie pas qu'il faille encourager les élèves à se tromper pour le plaisir. Ce qui compte, c'est le retour qu'ils reçoivent. Une erreur suivie d'une correction rapide et bienveillante est extrêmement formatrice. Une erreur sanctionnée sans explication, au contraire, ne produit que de l'anxiété."],["M","Certains systèmes éducatifs en ont tiré des conséquences concrètes. On y multiplie les petits tests, sans note, qui permettent aux élèves de repérer eux-mêmes ce qu'ils n'ont pas compris. Les résultats sont probants : les connaissances sont mieux retenues sur le long terme."],["M","Le véritable défi est donc culturel. Il s'agit de faire comprendre aux élèves, mais aussi aux parents et aux enseignants, que se tromper n'est pas un aveu de faiblesse, mais la condition même du progrès."]],"questions":[{"q":"Quel constat le chercheur fait-il sur les systèmes éducatifs ?","o":["L'erreur y est valorisée","L'erreur y est vécue comme un échec, voire comme une faute","L'erreur y est ignorée par les enseignants"],"a":1,"why":"«L'erreur est perçue comme un échec, voire comme une faute morale»."},{"q":"Selon les neurosciences, comment le cerveau apprend-il ?","o":["En répétant sans cesse la bonne réponse","En comparant ses prévisions avec ce qui se produit réellement","En évitant les situations nouvelles"],"a":1,"why":"El cerebro compara lo que había previsto con lo que ocurre: es la «señal de error»."},{"q":"D'après Marc Delorme, qu'est-ce qui rend une erreur formatrice ?","o":["Une sanction sévère","Une correction rapide et bienveillante","Le fait de la répéter plusieurs fois"],"a":1,"why":"«Une erreur suivie d'une correction rapide et bienveillante est extrêmement formatrice»."},{"q":"Quel est l'effet des petits tests sans note ?","o":["Les connaissances sont mieux retenues sur le long terme","Les élèves obtiennent de meilleures notes à court terme","Les enseignants gagnent du temps de correction"],"a":0,"why":"«Les connaissances sont mieux retenues sur le long terme»."},{"q":"Selon le conférencier, de quelle nature est le véritable défi ?","o":["Technologique","Financière","Culturelle"],"a":2,"why":"«Le véritable défi est donc culturel»: cambiar la percepción del error en alumnos, padres y docentes."}]}],"ce":[{"title":"Texte — Notre attention, une ressource à défendre","source":"Tribune publiée dans un magazine d'idées","text":"Notre attention, une ressource à défendre\n\nNous vivons dans un monde où l'information n'a jamais été aussi abondante. Mais, comme l'avait pressenti l'économiste Herbert Simon dès le début des années 1970, une abondance d'informations crée une pénurie d'attention. Cette ressource, limitée par nature, est devenue l'objet d'une concurrence acharnée. Réseaux sociaux, plateformes de vidéos, applications de jeux : tous se disputent les minutes, voire les secondes, de notre temps disponible.\n\nLe modèle économique de ces services explique largement cette course. Gratuits pour l'utilisateur, ils se financent par la publicité, dont les revenus dépendent directement du temps passé devant l'écran. Chaque fonctionnalité — défilement infini, lecture automatique, notifications, compteurs de « j'aime » — est donc conçue, testée et affinée pour retenir l'utilisateur le plus longtemps possible. Certains anciens ingénieurs de la Silicon Valley reconnaissent aujourd'hui avoir délibérément exploité des mécanismes psychologiques bien connus, comme la récompense imprévisible, qui rend si difficile de refermer une application.\n\nLes effets de cette captation sont encore débattus, mais plusieurs tendances inquiètent. Les enseignants constatent que leurs élèves peinent à se concentrer sur un texte long. Des chercheurs observent que la simple présence d'un téléphone sur la table, même éteint, peut réduire les performances lors d'exercices exigeants. Au-delà des individus, c'est le débat démocratique qui risque d'en pâtir : les contenus les plus choquants ou les plus polarisants étant ceux qui retiennent le mieux l'attention, les algorithmes tendent à les mettre en avant, au détriment de l'information nuancée.\n\nFaut-il pour autant céder au catastrophisme ? Rien n'est moins sûr. Chaque nouvelle technologie, de l'imprimerie à la télévision, a suscité des craintes comparables, qui se sont souvent révélées exagérées. Par ailleurs, ces mêmes outils permettent d'accéder à des cours gratuits, de maintenir des liens familiaux à distance ou de mobiliser des citoyens autour de causes communes. Le problème ne réside donc pas tant dans la technologie elle-même que dans les logiques économiques qui en orientent la conception.\n\nDès lors, plusieurs pistes se dessinent. La première relève de la responsabilité individuelle : désactiver les notifications, s'accorder des plages sans écran, réapprendre à s'ennuyer. Mais faire reposer tout l'effort sur l'utilisateur revient à ignorer l'asymétrie entre un individu isolé et des entreprises disposant de moyens considérables. D'où une deuxième piste, réglementaire : certains juristes proposent d'interdire les interfaces manipulatrices, ou d'imposer par défaut des réglages plus respectueux du temps des utilisateurs. La troisième piste, enfin, est éducative : apprendre dès l'école à comprendre le fonctionnement des plateformes, c'est donner aux futurs citoyens les moyens de reprendre la main.\n\nL'attention n'est pas une simple marchandise. Elle est la condition de toute pensée, de toute relation, de tout apprentissage. La défendre, c'est défendre notre capacité à choisir ce à quoi nous consacrons notre vie.","questions":[{"q":"Selon l'auteur, pourquoi l'attention est-elle devenue l'objet d'une concurrence ?","o":["Parce qu'elle est une ressource limitée face à une information surabondante","Parce que les gens lisent moins qu'autrefois","Parce que la publicité est interdite à la télévision"],"a":0,"why":"Retoma la idea de Herbert Simon: la abundancia de información crea una escasez de atención, recurso limitado."},{"q":"Quel lien l'auteur établit-il entre la gratuité des services et la captation de l'attention ?","o":["La gratuité oblige les plateformes à réduire la publicité","Les revenus publicitaires dépendent du temps passé devant l'écran","Les services gratuits sont financés par l'État"],"a":1,"why":"Los servicios gratuitos viven de la publicidad, «dont les revenus dépendent directement du temps passé devant l'écran»."},{"q":"Le mécanisme de la « récompense imprévisible » est cité pour expliquer…","o":["la difficulté à refermer une application","le succès des cours en ligne","la baisse des revenus publicitaires"],"a":0,"why":"Es un mecanismo psicológico «qui rend si difficile de refermer une application»."},{"q":"En quoi le débat démocratique peut-il être menacé, selon le texte ?","o":["Les algorithmes mettent en avant les contenus choquants ou polarisants","Les citoyens ne votent plus","Les journaux traditionnels ont disparu"],"a":0,"why":"Como los contenidos polarizantes retienen mejor la atención, los algoritmos los destacan en detrimento de la información matizada."},{"q":"Dans le quatrième paragraphe, l'auteur…","o":["rejette toute technologie numérique","nuance le discours alarmiste en rappelant les usages positifs de ces outils","affirme que toutes les craintes actuelles sont fondées"],"a":1,"why":"«Faut-il pour autant céder au catastrophisme ? Rien n'est moins sûr»: recuerda miedos exagerados del pasado y usos positivos."},{"q":"Pourquoi l'auteur juge-t-il insuffisante la seule responsabilité individuelle ?","o":["Parce que les utilisateurs manquent de volonté","Parce qu'il existe une asymétrie de moyens entre l'individu et les entreprises","Parce que les notifications ne peuvent pas être désactivées"],"a":1,"why":"Hacer recaer todo el esfuerzo en el usuario ignora «l'asymétrie entre un individu isolé et des entreprises disposant de moyens considérables»."},{"q":"Quelle thèse l'auteur défend-il en conclusion ?","o":["L'attention est une marchandise comme une autre","Défendre son attention, c'est préserver sa liberté de choisir sa vie","Il faut interdire les réseaux sociaux"],"a":1,"why":"«La défendre, c'est défendre notre capacité à choisir ce à quoi nous consacrons notre vie»."}]}],"pe":{"title":"Essai argumentatif","context":"A partir del texto sobre la economía de la atención, una revista universitaria francófona convoca ensayos sobre quién debe proteger nuestra atención: cada persona o la sociedad mediante reglas colectivas.","consigne":"Une revue universitaire francophone lance un appel à contributions sur le thème suivant : « Protéger notre attention : affaire de choix personnel ou de régulation collective ? » Dans un essai argumentatif structuré (introduction avec problématique, développement, conclusion), vous prendrez position sur cette question en vous appuyant sur des exemples précis. (250 mots minimum)","min":250,"max":320},"po":{"title":"Exposé — Une langue commune pour tous ?","doc":"Selon l'UNESCO, près de la moitié des quelque sept mille langues parlées dans le monde pourraient disparaître d'ici la fin du siècle. Dans le même temps, l'anglais s'impose comme la langue de la science, des affaires et d'Internet. Certains y voient un progrès : une langue commune faciliterait la circulation des idées et l'accès au savoir. D'autres défendent le multilinguisme comme une richesse culturelle et cognitive, et rappellent que chaque langue porte une manière singulière de penser le monde. En Colombie comme ailleurs, les politiques éducatives doivent arbitrer entre ces deux visions.","consigne":"À partir de ce document, vous préparerez un exposé sur le thème : « Une langue commune pour tous : progrès ou appauvrissement ? » Votre exposé comportera une introduction avec une problématique, un développement structuré en deux ou trois parties et une conclusion. Vous débattrez ensuite avec le jury.","consigne_es":"A partir del documento, prepara una exposición sobre el tema «¿Una lengua común para todos: progreso o empobrecimiento?», con introducción y problemática, desarrollo en dos o tres partes y conclusión. Después debatirás con el jurado.","prep_s":300,"talk_s":300,"tips":["No resumas el documento: úsalo solo para plantear la problemática.","Anuncia un plan claro (por ejemplo, ventajas de una lengua común / riesgos / propuesta de equilibrio).","Aporta ejemplos propios: lenguas indígenas y criollas de Colombia, el inglés en la universidad, tu experiencia con el francés.","En el debate, matiza y concede antes de refutar: «certes…, il n'en demeure pas moins que…»."]}}];
window.__ORAL=[{"id":"o-a1-1","level":"A1","type":"Monologue suivi","title":"Je me présente","prompt":"Présentez-vous : dites votre nom, votre âge, où vous habitez, ce que vous étudiez et ce que vous aimez faire.","prompt_es":"Preséntate en francés: nombre, edad, ciudad, carrera y gustos. Usa frases cortas y claras.","doc":"","prep_s":30,"talk_s":60,"useful":["Je m'appelle…","J'ai vingt ans.","J'habite à Pamplona, en Colombie.","Je suis étudiant(e) en…","J'aime… / Je n'aime pas…","Le week-end, je…"],"tips":["Prepara una frase para cada tema: así no te quedas en blanco.","En «j'habite» la h es muda: se pronuncia «jabit».","Si dudas, di «euh…» en francés en vez de pasar al español."]},{"id":"o-a1-2","level":"A1","type":"Monologue suivi","title":"Ma famille","prompt":"Parlez de votre famille : combien de personnes il y a, comment elles s'appellent, leur âge et leur profession.","prompt_es":"Describe a tu familia: cuántos son, sus nombres, edades y profesiones.","doc":"","prep_s":30,"talk_s":60,"useful":["Dans ma famille, il y a…","Mon père s'appelle…","Ma mère est infirmière.","J'ai un frère et deux sœurs.","Il/Elle a … ans.","Nous habitons ensemble à…"],"tips":["Después de «être», las profesiones van sin artículo: «elle est médecin».","Usa «mon» delante de una palabra femenina que empieza por vocal: «mon amie», «mon oncle»."]},{"id":"o-a1-3","level":"A1","type":"Exercice en interaction","title":"À la cafétéria","prompt":"Vous êtes à la cafétéria de l'université. Vous commandez un repas et une boisson, vous demandez le prix et vous payez. L'examinateur joue le rôle du serveur.","prompt_es":"Juego de roles: estás en la cafetería de la universidad. Pide comida y bebida, pregunta el precio y paga. El examinador es el mesero.","doc":"","prep_s":30,"talk_s":60,"useful":["Bonjour, je voudrais…","Qu'est-ce que vous avez comme boissons ?","Un jus d'orange, s'il vous plaît.","C'est combien ?","Je peux payer par carte ?","Merci, bonne journée !"],"tips":["Usa «je voudrais» en lugar de «je veux»: es mucho más cortés.","Saluda y despídete siempre: la cortesía forma parte de la evaluación."]},{"id":"o-a1-4","level":"A1","type":"Monologue suivi","title":"Ma journée","prompt":"Décrivez une journée typique : à quelle heure vous vous levez, vos cours, vos repas et vos activités du soir.","prompt_es":"Describe un día normal de tu vida: a qué hora te levantas, tus clases, tus comidas y lo que haces por la noche.","doc":"","prep_s":30,"talk_s":60,"useful":["Je me lève à six heures.","Je prends le bus pour aller à l'université.","J'ai cours de huit heures à midi.","Je déjeune avec mes amis.","Le soir, je fais mes devoirs.","Je me couche vers onze heures."],"tips":["Los verbos pronominales (se lever, se coucher) llevan «me» con «je»: «je me lève».","Ordena tu relato con «d'abord», «ensuite», «après» y «enfin»."]},{"id":"o-a2-1","level":"A2","type":"Monologue suivi","title":"Mes dernières vacances","prompt":"Racontez vos dernières vacances : où vous êtes allé(e), avec qui, ce que vous avez fait et ce que vous avez pensé de ce voyage.","prompt_es":"Cuenta tus últimas vacaciones: adónde fuiste, con quién, qué hiciste y qué te pareció.","doc":"","prep_s":60,"talk_s":90,"useful":["L'année dernière, je suis allé(e) à…","J'ai voyagé avec…","Nous avons visité…","Il faisait très chaud.","C'était magnifique !","Ce que j'ai préféré, c'est…","J'aimerais y retourner."],"tips":["Usa el passé composé para las acciones y el imparfait para describir (clima, ambiente).","Aller, venir, partir y arriver se conjugan con «être»: «je suis allée»."]},{"id":"o-a2-2","level":"A2","type":"Exercice en interaction","title":"Proposer une sortie","prompt":"Vous proposez à un(e) ami(e) français(e) d'aller à un concert ce week-end. Vous fixez ensemble le jour, l'heure et le lieu de rendez-vous. L'examinateur joue le rôle de l'ami(e), qui n'est pas toujours disponible.","prompt_es":"Invita a un amigo francés a un concierto este fin de semana y pónganse de acuerdo en día, hora y lugar de encuentro. El examinador hace de amigo y no siempre está disponible.","doc":"","prep_s":60,"talk_s":90,"useful":["Ça te dit d'aller à… ?","Tu es libre samedi soir ?","On se retrouve où ?","Rendez-vous à huit heures devant…","Désolé(e), je ne peux pas…","Et dimanche, ça t'irait ?","D'accord, c'est parfait !"],"tips":["Con un amigo se usa «tu», no «vous».","Si el examinador rechaza tu propuesta, ofrece otra opción: así demuestras que sabes negociar."]},{"id":"o-a2-3","level":"A2","type":"Exercice en interaction","title":"Une chambre en colocation","prompt":"Vous cherchez une chambre près de l'université. Vous téléphonez au propriétaire pour vous renseigner sur le loyer, les charges, l'équipement et pour organiser une visite. L'examinateur joue le rôle du propriétaire.","prompt_es":"Buscas una habitación cerca de la universidad. Llamas al propietario para preguntar por el arriendo, los servicios, el equipamiento y para acordar una visita.","doc":"","prep_s":60,"talk_s":90,"useful":["Bonjour, j'appelle pour l'annonce de la chambre.","Le loyer est de combien ?","Les charges sont comprises ?","Est-ce que la chambre est meublée ?","Il y a Internet ?","Est-ce que je pourrais la visiter demain ?"],"tips":["Aquí usa «vous»: hablas con un desconocido.","Prepara 4 o 5 preguntas con estructuras distintas: «est-ce que», inversión y entonación."]},{"id":"o-a2-4","level":"A2","type":"Monologue suivi","title":"Un lieu que j'aime","prompt":"Présentez un lieu de votre région que vous aimez beaucoup : un parc, une place, un village, un paysage… Décrivez-le et expliquez pourquoi vous l'aimez.","prompt_es":"Presenta un lugar de tu región que te guste mucho (un parque, una plaza, un pueblo, un paisaje). Descríbelo y explica por qué te gusta.","doc":"","prep_s":60,"talk_s":75,"useful":["Le lieu que je préfère, c'est…","Il se trouve à … kilomètres de…","Il y a beaucoup de…","On peut s'y promener et y manger…","J'y vais souvent avec…","Je l'aime parce que…"],"tips":["El pronombre «y» reemplaza un lugar: «j'y vais le dimanche».","Da detalles concretos (colores, clima, comida típica) para enriquecer la descripción."]},{"id":"o-b1-1","level":"B1","type":"Monologue suivi","title":"Un professeur qui m'a marqué","prompt":"Parlez d'un professeur qui a eu une influence importante sur vous. Expliquez qui il ou elle était, ce qu'il ou elle vous a appris et pourquoi vous vous en souvenez encore aujourd'hui.","prompt_es":"Habla de un profesor o profesora que te marcó: quién era, qué te enseñó y por qué todavía lo recuerdas.","doc":"","prep_s":120,"talk_s":120,"useful":["Je me souviens d'un professeur qui…","Il/Elle nous encourageait à…","Grâce à lui/elle, j'ai compris que…","Ce qui m'a le plus marqué, c'est…","Aujourd'hui encore, je…","Si je devais le/la décrire en un mot…"],"tips":["Combina el imparfait (hábitos, descripción) con el passé composé (hechos puntuales).","Termina con una reflexión personal: el jurado valora que expliques el impacto en tu vida."]},{"id":"o-b1-2","level":"B1","type":"Exercice en interaction","title":"Un colocataire bruyant","prompt":"Votre colocataire écoute de la musique très fort tard le soir, alors que vous préparez vos examens. Vous lui parlez pour trouver une solution. L'examinateur joue le rôle du colocataire, qui ne voit pas le problème.","prompt_es":"Tu compañero de apartamento pone música muy fuerte de noche y tú estás preparando exámenes. Habla con él para encontrar una solución. El examinador hace de compañero y no ve el problema.","doc":"","prep_s":60,"talk_s":120,"useful":["Je voulais te parler de quelque chose…","Je ne sais pas si tu t'en rends compte, mais…","Ça me gêne parce que…","Est-ce que tu pourrais… ?","Et si on fixait une heure limite ?","Je comprends ton point de vue, mais…","Alors, on est d'accord ?"],"tips":["Mantén un tono cortés aunque el examinador se muestre difícil.","Propón soluciones concretas (horarios, audífonos) y cierra con un acuerdo claro."]},{"id":"o-b1-3","level":"B1","type":"Point de vue","title":"Cours en ligne ou en présentiel ?","prompt":"Depuis quelques années, beaucoup d'universités proposent des cours en ligne. À votre avis, est-ce une bonne solution pour les étudiants ? Donnez votre opinion en l'illustrant par des exemples.","prompt_es":"Muchas universidades ofrecen hoy clases virtuales. ¿Es una buena solución para los estudiantes? Da tu opinión con ejemplos.","doc":"","prep_s":120,"talk_s":150,"useful":["À mon avis,…","D'un côté…, de l'autre…","L'avantage principal, c'est que…","Par contre,…","Par exemple, dans mon université,…","Pour conclure, je pense que…"],"tips":["Estructura: introducción, dos o tres argumentos con ejemplos y conclusión.","Los ejemplos de tu propia experiencia universitaria son los más convincentes."]},{"id":"o-b1-4","level":"B1","type":"Monologue suivi","title":"Pourquoi j'apprends le français","prompt":"Expliquez pourquoi vous avez choisi d'apprendre le français, quelles difficultés vous rencontrez et quels sont vos projets avec cette langue.","prompt_es":"Explica por qué decidiste aprender francés, qué dificultades encuentras y qué proyectos tienes con este idioma.","doc":"","prep_s":120,"talk_s":120,"useful":["J'ai commencé à apprendre le français parce que…","Ce qui me semble le plus difficile, c'est…","Pour progresser, j'essaie de…","Le français me permettra de…","J'aimerais un jour…","Je trouve que…"],"tips":["Usa el condicional (j'aimerais, je voudrais) para hablar de tus proyectos.","Menciona estrategias concretas: series, música, aplicaciones, intercambios de conversación."]},{"id":"o-b1-5","level":"B1","type":"Exercice en interaction","title":"Demander un délai","prompt":"À cause d'un problème familial, vous n'avez pas pu terminer un travail important. Vous allez voir votre professeur pour lui demander un délai supplémentaire. L'examinateur joue le rôle du professeur, qui hésite à accepter.","prompt_es":"Por un problema familiar no pudiste terminar un trabajo importante. Pides a tu profesor más plazo. El examinador hace de profesor y duda en aceptar.","doc":"","prep_s":60,"talk_s":120,"useful":["Excusez-moi de vous déranger…","Je voulais vous demander s'il serait possible de…","J'ai eu un problème familial…","Je sais que la date limite était…","Je pourrais vous le rendre avant…","Je peux vous montrer ce que j'ai déjà fait.","Je vous remercie de votre compréhension."],"tips":["Registro formal: «vous» y condicional de cortesía.","Justifica tu solicitud y propone una fecha precisa: demuestra responsabilidad."]},{"id":"o-b1-6","level":"B1","type":"Point de vue","title":"Travailler pendant ses études","prompt":"Beaucoup d'étudiants ont un emploi en même temps qu'ils étudient. Est-ce une expérience enrichissante ou un obstacle à la réussite ? Donnez votre point de vue.","prompt_es":"Muchos estudiantes trabajan mientras estudian. ¿Es una experiencia enriquecedora o un obstáculo para el éxito académico? Da tu punto de vista.","doc":"","prep_s":120,"talk_s":150,"useful":["Il est vrai que…","Cependant,…","Travailler permet de…","Le risque, c'est de…","Dans mon cas,…","Tout dépend de…","En conclusion,…"],"tips":["Presenta ventajas e inconvenientes antes de dar tu opinión final.","Varía los conectores (cependant, en revanche, de plus): suben tu nota."]},{"id":"o-b2-1","level":"B2","type":"Point de vue","title":"Le portable en cours","prompt":"Dégagez le problème soulevé par ce document, puis présentez votre opinion de manière argumentée. L'examinateur pourra ensuite vous poser des questions pour vous faire préciser ou défendre votre point de vue.","prompt_es":"Lee el documento, identifica el problema que plantea y defiende tu opinión con argumentos y ejemplos. Después, el examinador te hará preguntas o te llevará la contraria.","doc":"Plusieurs universités envisagent d'interdire les téléphones portables pendant les cours. Selon les défenseurs de cette mesure, elle améliorerait la concentration et favoriserait les échanges entre étudiants. Ses opposants rappellent au contraire que le téléphone est devenu un véritable outil de travail : on y consulte des dictionnaires, des articles scientifiques ou la plateforme de l'université. Pour eux, mieux vaudrait apprendre aux étudiants à maîtriser leur usage plutôt que de l'interdire.","prep_s":300,"talk_s":180,"useful":["Ce document pose la question de savoir si…","Il s'agit d'un sujet qui divise…","Je suis plutôt favorable à… / opposé(e) à…","Force est de constater que…","Il ne faut pas oublier que…","On pourrait envisager un compromis :…","En définitive,…"],"tips":["Empieza presentando el tema del documento en una o dos frases, sin leerlo en voz alta.","Anuncia tu plan (d'abord…, ensuite…, enfin…) y apoya cada argumento con un ejemplo concreto.","Prepárate para las objeciones del examinador: reformula su idea antes de responder."]},{"id":"o-b2-2","level":"B2","type":"Point de vue","title":"Un service social obligatoire ?","prompt":"Dégagez le problème soulevé par ce document, puis présentez votre opinion de manière argumentée. L'examinateur pourra ensuite vous poser des questions pour vous faire préciser ou défendre votre point de vue.","prompt_es":"Lee el documento, identifica el problema que plantea y defiende tu opinión con argumentos y ejemplos. Después, el examinador te hará preguntas o te llevará la contraria.","doc":"Dans certains pays, les étudiants doivent consacrer plusieurs dizaines d'heures à des activités d'intérêt général pour obtenir leur diplôme : soutien scolaire dans des quartiers défavorisés, aide aux personnes âgées, projets environnementaux… Les partisans de cette obligation y voient une façon de rapprocher l'université de la société. Ses détracteurs estiment qu'un engagement imposé perd son sens et qu'il pénalise les étudiants qui travaillent déjà pour financer leurs études.","prep_s":300,"talk_s":180,"useful":["Ce document pose la question de savoir si…","Il s'agit d'un sujet qui divise…","Je suis plutôt favorable à… / opposé(e) à…","Force est de constater que…","Il ne faut pas oublier que…","On pourrait envisager un compromis :…","En définitive,…"],"tips":["Empieza presentando el tema del documento en una o dos frases, sin leerlo en voz alta.","Anuncia tu plan (d'abord…, ensuite…, enfin…) y apoya cada argumento con un ejemplo concreto.","Prepárate para las objeciones del examinador: reformula su idea antes de responder."]},{"id":"o-b2-3","level":"B2","type":"Point de vue","title":"Le tourisme, chance ou menace ?","prompt":"Dégagez le problème soulevé par ce document, puis présentez votre opinion de manière argumentée. L'examinateur pourra ensuite vous poser des questions pour vous faire préciser ou défendre votre point de vue.","prompt_es":"Lee el documento, identifica el problema que plantea y defiende tu opinión con argumentos y ejemplos. Después, el examinador te hará preguntas o te llevará la contraria.","doc":"En dix ans, le nombre de visiteurs étrangers en Colombie a fortement augmenté. Des villes comme Carthagène ou Santa Marta profitent de cette manne : création d'emplois, rénovation du patrimoine, ouverture internationale. Mais les habitants de certains quartiers historiques dénoncent la hausse des loyers, la transformation des logements en locations touristiques et la pression sur les ressources naturelles. Comment concilier développement touristique et qualité de vie des populations locales ?","prep_s":300,"talk_s":210,"useful":["Ce document pose la question de savoir si…","Il s'agit d'un sujet qui divise…","Je suis plutôt favorable à… / opposé(e) à…","Force est de constater que…","Il ne faut pas oublier que…","On pourrait envisager un compromis :…","En définitive,…"],"tips":["Empieza presentando el tema del documento en una o dos frases, sin leerlo en voz alta.","Anuncia tu plan (d'abord…, ensuite…, enfin…) y apoya cada argumento con un ejemplo concreto.","Prepárate para las objeciones del examinador: reformula su idea antes de responder."]},{"id":"o-b2-4","level":"B2","type":"Point de vue","title":"L'intelligence artificielle et les devoirs","prompt":"Dégagez le problème soulevé par ce document, puis présentez votre opinion de manière argumentée. L'examinateur pourra ensuite vous poser des questions pour vous faire préciser ou défendre votre point de vue.","prompt_es":"Lee el documento, identifica el problema que plantea y defiende tu opinión con argumentos y ejemplos. Después, el examinador te hará preguntas o te llevará la contraria.","doc":"Selon plusieurs enquêtes menées dans des universités, une large majorité d'étudiants reconnaît utiliser des outils d'intelligence artificielle pour rédiger ses travaux. Certains enseignants y voient une forme de tricherie et réclament un retour aux examens sur table. D'autres considèrent que ces outils font désormais partie du monde professionnel et qu'il faut apprendre à s'en servir de manière critique, en vérifiant les informations produites et en indiquant clairement ce qui vient de la machine.","prep_s":300,"talk_s":210,"useful":["Ce document pose la question de savoir si…","Il s'agit d'un sujet qui divise…","Je suis plutôt favorable à… / opposé(e) à…","Force est de constater que…","Il ne faut pas oublier que…","On pourrait envisager un compromis :…","En définitive,…"],"tips":["Empieza presentando el tema del documento en una o dos frases, sin leerlo en voz alta.","Anuncia tu plan (d'abord…, ensuite…, enfin…) y apoya cada argumento con un ejemplo concreto.","Prepárate para las objeciones del examinador: reformula su idea antes de responder."]},{"id":"o-b2-5","level":"B2","type":"Point de vue","title":"Étudier à l'étranger","prompt":"Dégagez le problème soulevé par ce document, puis présentez votre opinion de manière argumentée. L'examinateur pourra ensuite vous poser des questions pour vous faire préciser ou défendre votre point de vue.","prompt_es":"Lee el documento, identifica el problema que plantea y defiende tu opinión con argumentos y ejemplos. Después, el examinador te hará preguntas o te llevará la contraria.","doc":"Chaque année, des milliers de jeunes Latino-Américains partent faire un master en Europe ou en Amérique du Nord. Pour beaucoup, c'est une occasion unique d'acquérir des compétences et d'élargir leurs horizons. Mais une partie d'entre eux ne revient jamais. Certains économistes parlent de « fuite des cerveaux » et s'inquiètent pour le développement de leur pays d'origine ; d'autres rappellent que la diaspora envoie de l'argent, crée des réseaux et transmet des savoirs.","prep_s":300,"talk_s":240,"useful":["Ce document pose la question de savoir si…","Il s'agit d'un sujet qui divise…","Je suis plutôt favorable à… / opposé(e) à…","Force est de constater que…","Il ne faut pas oublier que…","On pourrait envisager un compromis :…","En définitive,…"],"tips":["Empieza presentando el tema del documento en una o dos frases, sin leerlo en voz alta.","Anuncia tu plan (d'abord…, ensuite…, enfin…) y apoya cada argumento con un ejemplo concreto.","Prepárate para las objeciones del examinador: reformula su idea antes de responder."]},{"id":"o-b2-6","level":"B2","type":"Point de vue","title":"La voiture en ville","prompt":"Dégagez le problème soulevé par ce document, puis présentez votre opinion de manière argumentée. L'examinateur pourra ensuite vous poser des questions pour vous faire préciser ou défendre votre point de vue.","prompt_es":"Lee el documento, identifica el problema que plantea y defiende tu opinión con argumentos y ejemplos. Después, el examinador te hará preguntas o te llevará la contraria.","doc":"Pico y placa, journées sans voiture, pistes cyclables : les grandes villes colombiennes multiplient les mesures pour réduire la circulation automobile. Chaque dimanche, Bogotá ferme plus de cent kilomètres de routes aux voitures pour sa célèbre ciclovía. Pourtant, de nombreux automobilistes jugent ces mesures injustes : selon eux, les transports publics restent insuffisants et la voiture demeure indispensable pour aller travailler. Faut-il aller plus loin et limiter encore la place de la voiture en ville ?","prep_s":300,"talk_s":240,"useful":["Ce document pose la question de savoir si…","Il s'agit d'un sujet qui divise…","Je suis plutôt favorable à… / opposé(e) à…","Force est de constater que…","Il ne faut pas oublier que…","On pourrait envisager un compromis :…","En définitive,…"],"tips":["Empieza presentando el tema del documento en una o dos frases, sin leerlo en voz alta.","Anuncia tu plan (d'abord…, ensuite…, enfin…) y apoya cada argumento con un ejemplo concreto.","Prepárate para las objeciones del examinador: reformula su idea antes de responder."]},{"id":"o-c1-1","level":"C1","type":"Exposé","title":"Protéger les páramos","prompt":"À partir de ce document, préparez un exposé structuré (introduction avec une problématique, développement en deux ou trois parties, conclusion) sur le thème suivant : peut-on concilier développement économique et protection de l'environnement ? Vous défendrez ensuite votre position face au jury.","prompt_es":"Prepara una exposición estructurada (introducción con problemática, desarrollo en dos o tres partes, conclusión) sobre el conflicto entre desarrollo económico y protección ambiental. Luego debatirás con el jurado.","doc":"Les páramos, ces écosystèmes de haute montagne propres aux Andes, fournissent une grande partie de l'eau consommée dans les villes colombiennes. Or certains d'entre eux abritent aussi des gisements d'or convoités par des entreprises minières. Le cas du páramo de Santurbán, près de Bucaramanga, a donné lieu à d'importantes mobilisations citoyennes. Emplois et recettes fiscales d'un côté, protection de l'eau et de la biodiversité de l'autre : le débat dépasse largement la région.","prep_s":300,"talk_s":240,"useful":["Ce document soulève une question cruciale :…","Il convient dans un premier temps de…","Certes…, mais il n'en demeure pas moins que…","Cela nous amène à nous demander si…","À cet égard,…","Loin de s'opposer, ces deux logiques pourraient…","Pour conclure, il apparaît que…"],"tips":["Formula una problemática en forma de pregunta y anuncia tu plan en la introducción.","No resumas el documento: úsalo como punto de partida y aporta tus propios ejemplos y conocimientos.","Controla el tiempo: unos 30 s de introducción, 3 min de desarrollo y 30 s de conclusión."]},{"id":"o-c1-2","level":"C1","type":"Exposé","title":"Les langues autochtones","prompt":"À partir de ce document, préparez un exposé structuré (introduction avec une problématique, développement en deux ou trois parties, conclusion) sur le thème suivant : l'État doit-il intervenir pour sauver les langues minoritaires ? Vous défendrez ensuite votre position face au jury.","prompt_es":"Prepara una exposición estructurada sobre si el Estado debe intervenir para preservar las lenguas minoritarias. Luego debatirás con el jurado.","doc":"La Colombie reconnaît officiellement plus de soixante langues autochtones, auxquelles s'ajoutent notamment deux langues créoles, le romani et la langue des signes colombienne. Pourtant, plusieurs d'entre elles ne comptent plus que quelques centaines de locuteurs. Pour certains linguistes, la disparition d'une langue équivaut à la perte d'une bibliothèque entière de savoirs sur la nature, la médecine ou l'histoire. D'autres soulignent que les jeunes générations choisissent librement l'espagnol, langue de l'emploi et des études.","prep_s":300,"talk_s":240,"useful":["Ce document soulève une question cruciale :…","Il convient dans un premier temps de…","Certes…, mais il n'en demeure pas moins que…","Cela nous amène à nous demander si…","À cet égard,…","Loin de s'opposer, ces deux logiques pourraient…","Pour conclure, il apparaît que…"],"tips":["Formula una problemática en forma de pregunta y anuncia tu plan en la introducción.","No resumas el documento: úsalo como punto de partida y aporta tus propios ejemplos y conocimientos.","Controla el tiempo: unos 30 s de introducción, 3 min de desarrollo y 30 s de conclusión."]},{"id":"o-c1-3","level":"C1","type":"Exposé","title":"Le télétravail et la ville","prompt":"À partir de ce document, préparez un exposé structuré (introduction avec une problématique, développement en deux ou trois parties, conclusion) sur le thème suivant : le télétravail va-t-il transformer durablement nos territoires ? Vous défendrez ensuite votre position face au jury.","prompt_es":"Prepara una exposición estructurada sobre si el teletrabajo transformará de forma duradera las ciudades y las regiones. Luego debatirás con el jurado.","doc":"Depuis la pandémie, le télétravail s'est installé durablement dans de nombreux secteurs. Certains salariés ont quitté les capitales pour des villes moyennes ou des villages, attirés par des loyers plus bas et une meilleure qualité de vie. Les commerces des quartiers d'affaires, eux, voient leur clientèle diminuer. Pour certains urbanistes, cette évolution pourrait rééquilibrer les territoires ; pour d'autres, elle creuse l'écart entre ceux qui peuvent travailler à distance et ceux dont le métier exige une présence physique.","prep_s":300,"talk_s":240,"useful":["Ce document soulève une question cruciale :…","Il convient dans un premier temps de…","Certes…, mais il n'en demeure pas moins que…","Cela nous amène à nous demander si…","À cet égard,…","Loin de s'opposer, ces deux logiques pourraient…","Pour conclure, il apparaît que…"],"tips":["Formula una problemática en forma de pregunta y anuncia tu plan en la introducción.","No resumas el documento: úsalo como punto de partida y aporta tus propios ejemplos y conocimientos.","Controla el tiempo: unos 30 s de introducción, 3 min de desarrollo y 30 s de conclusión."]},{"id":"o-c1-4","level":"C1","type":"Exposé","title":"La lutte contre la désinformation","prompt":"À partir de ce document, préparez un exposé structuré (introduction avec une problématique, développement en deux ou trois parties, conclusion) sur le thème suivant : qui doit lutter contre la désinformation, et avec quels moyens ? Vous défendrez ensuite votre position face au jury.","prompt_es":"Prepara una exposición estructurada sobre quién debe combatir la desinformación y cómo hacerlo sin amenazar la libertad de expresión. Luego debatirás con el jurado.","doc":"Selon plusieurs travaux de recherche, les fausses informations se propagent plus vite et plus loin que les informations vérifiées sur les réseaux sociaux. Face à ce phénomène, certains États ont adopté des lois obligeant les plateformes à retirer rapidement les contenus mensongers. Des défenseurs des libertés publiques craignent toutefois que ces lois ne servent à censurer des opinions dérangeantes. D'autres misent plutôt sur l'éducation aux médias dès l'école.","prep_s":300,"talk_s":240,"useful":["Ce document soulève une question cruciale :…","Il convient dans un premier temps de…","Certes…, mais il n'en demeure pas moins que…","Cela nous amène à nous demander si…","À cet égard,…","Loin de s'opposer, ces deux logiques pourraient…","Pour conclure, il apparaît que…"],"tips":["Formula una problemática en forma de pregunta y anuncia tu plan en la introducción.","No resumas el documento: úsalo como punto de partida y aporta tus propios ejemplos y conocimientos.","Controla el tiempo: unos 30 s de introducción, 3 min de desarrollo y 30 s de conclusión."]}];
